/* 

1. In a test-first manner, create a simple class class StringCalculator with a method public int Add(string numbers)
  1. The method can take 0, 1 or 2 numbers, and will return their sum
  (for an empty string it will return 0): “” == 0 , “1” == 1 , “1,2” == 3

  2. Start with the simplest test case of an empty string and move to one & two
  numbers

  3. Remember to solve things as simply as possible so that you force yourself to
  write tests you did not think about

  4. Remember to refactor after each passing test

2. Allow the Add method to handle an unknown amount of numbers

3. Allow the Add method to handle new lines between numbers (instead of commas).
  1. the following input is ok: “1\n2,3” == 6
  2. the following is INVALID input so do not expect it : “1,\n” (not need to write a test for it)

4. Support different delimiters:
  to change a delimiter, the beginning of the string will contain a separate line that looks like this: “//[delimiter]\n[numbers…]”: “//;\n1;2” == 3

  since the default delimiter is ‘;’ .
  Note: All existing scenarios and tests should still be supported

5. Calling Add with a negative number will throw an exception “negatives not allowed” - and the negative that was passed.

6. If there are multiple negatives, show all of them in the exception message

7. Using TDD, Add a method to StringCalculator called public int GetCalledCount() that returns how many times Add() was invoked.
  Remember - Start with a failing (or even non compiling) test.

8. SKIP

9. Numbers bigger than 1000 should be ignored, for example: 2 + 1001 == 2

10. Delimiters can be of any length with the following format: //[delimiter]\n”, “//[***]\n1***2***3” == 6

11. Allow multiple delimiters like this: “//[delim1][delim2]\n”, “//[*][%]\n1*2%3” == 6.

12. make sure you can also handle multiple delimiters with length longer than one char: “//[**][%%]\n1**2%%3” == 6.

Driver:
V

Nav:
D

Time (8 minute blocks):
M

*/

import { StringCalc } from "../stringCalc";

describe("String calculator", () => {
  let stringCalc: StringCalc;

  beforeEach(() => {
    stringCalc = new StringCalc();
  });

  it("should take an empty string", () => {
    const result = stringCalc.add("");
    expect(result).toBe(0);
  });

  it("should return the value when passed only one", () => {
    const result = stringCalc.add("1");
    expect(result).toBe(1);
  });

  it("should add a string with 2 values", () => {
    const result = stringCalc.add("1,2");
    expect(result).toBe(3);
  });

  it('should add a string with a baggilion #s', () => {
    const result = stringCalc.add("1,2,3,4");
    expect(result).toBe(10);
  })

  it('should handle new lines and commas', () => {
    const result = stringCalc.add("1,2\n3,4");
    expect(result).toBe(10);

  })

  it('should support custom delimiters outline by //', () => {
    const result = stringCalc.add("//;\n1;2");
    expect(result).toBe(3);

  })





});

const PAGE_POST_COUNT = 5;

const feedUrls = ["/", "/category/tech", "/tag/programming"];

feedUrls.forEach((url) => {
  describe(`Feed page ${url}`, () => {
    beforeEach(() => {
      cy.visit(url);
      cy.waitForRouteChange();

      cy.get("main > div > div").as("feed");
    });

    it("loads the initial posts properly", () => {
      cy.get("@feed").children().should("have.length", PAGE_POST_COUNT);

      // Make sure the first page posts get loaded properly
      cy.findByText("Big Test");
      cy.findByText("Storms of Doors");
      cy.findByText("Valley in the Storms");
      cy.findByText("The Darkest Something");
      cy.findByText("Flames in the Time");
    });

    it("correctly navigates to the Big Test post via title", () => {
      cy.findByText("Big Test").click();
      cy.waitForRouteChange();

      cy.url().should("contain", "/big-sample-test");
    });

    it("correctly navigates to the Big Test post via cover image", () => {
      cy.findByAltText(
        "An image tagged as nature and water for the big test."
      ).click();
      cy.waitForRouteChange();

      cy.url().should("contain", "/big-sample-test");
    });

    it("contains post excerpt", () => {
      cy.findByText(
        'NOTE: This "post" is based on Markdown Cheatsheet and is meant to test styling of Markdown generated documents. This is intended as a…'
      );
    });

    it("has functioning infinite scrolling", () => {
      cy.get("@feed").children().should("have.length", PAGE_POST_COUNT);

      // Scroll to bottom and check the amount of loaded posts
      cy.scrollTo("bottom");

      cy.get("@feed")
        .children()
        .should("have.length", PAGE_POST_COUNT * 2);
    });

    it("keeps fetched infinite scroll pages in cache for faster access between page navigation", () => {
      cy.on("uncaught:exception", () => false);

      // Load a single scroll page
      cy.scrollTo("bottom");
      cy.get("@feed")
        .children()
        .should("have.length", PAGE_POST_COUNT * 2);

      // Make sure navigating between pages doesn't clear the cache
      cy.findByText("Big Test").click();
      cy.waitForRouteChange();

      cy.go("back");
      cy.waitForRouteChange();

      cy.get("@feed")
        .children()
        .should("have.length", PAGE_POST_COUNT * 2);
    });
  });
});

// Aided with basic GitHub coding tools
import * as vscode from "vscode";
import { WorkspaceTaskManager } from "./models/task-manager";
import { ITask, TaskStatus } from "./models/task";
import { TaskEditor } from "./views/task-editor";
import { TaskDocumentHelper } from "./task-document-helper";
import { TaskParser } from "./models/task-parser";
import { TaskTreeItem } from "./views/task-tree-item";

export class TaskCommands {
  private taskManager: WorkspaceTaskManager;

  constructor(taskManager: WorkspaceTaskManager) {
    this.taskManager = taskManager;
  }

  public registerCommands(context: vscode.ExtensionContext): void {
    context.subscriptions.push(
      vscode.commands.registerCommand(
        "vstasks.createTask",
        this.createTask.bind(this)
      ),
      vscode.commands.registerCommand(
        "vstasks.toggleTaskStatus",
        this.toggleTaskStatus.bind(this)
      ),
      vscode.commands.registerCommand(
        "vstasks.editTask",
        this.editTask.bind(this)
      ),
      vscode.commands.registerCommand(
        "vstasks.deleteTask",
        this.deleteTask.bind(this)
      ),
      vscode.commands.registerCommand(
        "vstasks.showAllTasks",
        this.showAllTasks.bind(this)
      ),
      vscode.commands.registerCommand(
        "vstasks.showTasksByTag",
        this.showTasksByTag.bind(this)
      ),
      vscode.commands.registerCommand(
        "vstasks.runCustomQuery",
        this.runCustomQuery.bind(this)
      )
    );
  }

  public async createTask(): Promise<void> {
    try {
      vscode.window.showInformationMessage("Creating new task...");
      // TODO: Implement task creation dialog
    } catch (err) {
      vscode.window.showErrorMessage(`Failed to create task: ${err}`);
    }
  }

  public async toggleTaskStatus(taskOrId?: ITask | string): Promise<void> {
    // Aided with basic GitHub coding tools
    try {
      let task: ITask | undefined;
      // Handle TaskTreeItem from tree view context menu
      if (taskOrId instanceof TaskTreeItem && taskOrId.task) {
        task = taskOrId.task;
      } else if (
        typeof taskOrId === "object" &&
        taskOrId &&
        "task" in taskOrId &&
        (taskOrId as { task?: ITask }).task
      ) {
        // fallback for plain object (e.g. from tests or serialization)
        task = (taskOrId as { task?: ITask }).task;
      } else if (typeof taskOrId === "string") {
        task = this.taskManager.getAllTasks().find((t) => t.id === taskOrId);
      } else {
        task = taskOrId as ITask;
      }
      if (!task) {
        vscode.window.showErrorMessage("No task selected");
        return;
      }
      // 新しいステータスを決定
      const toggledStatus: TaskStatus =
        task.status === TaskStatus.DONE ? TaskStatus.TODO : TaskStatus.DONE;
      // descriptionからインライン表現を除去
      const pureDescription = TaskEditor.extractPureTitle(task.description);

      // Ensure pureDescription is a string before processing
      const processedDescription =
        typeof pureDescription === "string"
          ? pureDescription
          : task.description || "";

      // ✅ 完了日表現もdescriptionから除去
      const descriptionAfterRemoval = processedDescription
        .replace(/✅\s*\d{4}-\d{2}-\d{2}/g, "")
        .trim();

      // タグ抽出はpureDescriptionではなく元のdescriptionから行う
      const parser = new TaskParser();
      const priority = parser.extractPriority(descriptionAfterRemoval);
      // Extract tags from the original description to avoid losing them
      const tags = parser.extractTags(task.description);
      const { dueDate, scheduledDate } = parser.extractDates(
        descriptionAfterRemoval
      );
      const recurrence = parser.extractRecurrence(descriptionAfterRemoval);
      // 完了日: DONEのときのみ現在日付、それ以外はundefined
      const completedDate =
        toggledStatus === TaskStatus.DONE ? new Date() : undefined;
      const updatedTask: ITask = {
        ...task,
        status: toggledStatus,
        completedDate,
        description: descriptionAfterRemoval,
        priority,
        tags,
        dueDate,
        scheduledDate,
        recurrence,
      };
      // descriptionがクリーンな状態でrawTextを生成
      updatedTask.rawText = TaskParser.generateTaskLine(updatedTask);
      // Markdownファイルの該当行を置換
      const openEditor = vscode.window.visibleTextEditors.find(
        (ed) => ed.document.uri.fsPath === task.filePath
      );
      if (openEditor) {
        await TaskDocumentHelper.updateTaskInDocument(
          openEditor.document,
          task,
          updatedTask
        );
      } else {
        // ファイルが開かれていない場合は開いて編集
        const doc = await vscode.workspace.openTextDocument(task.filePath);
        await TaskDocumentHelper.updateTaskInDocument(doc, task, updatedTask);
      }
      // メモリ上のタスクも更新
      this.taskManager.updateTask(task.id, {
        status: toggledStatus,
        completedDate:
          toggledStatus === TaskStatus.DONE ? new Date() : undefined,
        rawText: updatedTask.rawText,
      });
      vscode.window.showInformationMessage("Task status toggled");
    } catch (err) {
      vscode.window.showErrorMessage(`Error toggling task status: ${err}`);
    }
  }

  public async editTask(task?: ITask): Promise<void> {
    try {
      if (!task) {
        vscode.window.showErrorMessage("No task selected");
        return;
      }
      const editor = vscode.window.activeTextEditor;
      if (!editor || editor.document.languageId !== "markdown") {
        vscode.window.showErrorMessage("No active markdown editor");
        return;
      }
      const updated = await TaskEditor.showEditDialog(task);
      if (!updated) {
        vscode.window.showInformationMessage("編集がキャンセルされました");
        return;
      }
      // rawText再生成
      updated.rawText = TaskParser.generateTaskLine(updated);
      await TaskDocumentHelper.updateTaskInDocument(
        editor.document,
        task,
        updated
      );
      vscode.window.showInformationMessage("タスクを編集しました");
    } catch (err) {
      vscode.window.showErrorMessage(`Failed to edit task: ${err}`);
    }
  }

  public async deleteTask(task?: ITask): Promise<void> {
    try {
      if (!task) {
        vscode.window.showErrorMessage("No task selected");
        return;
      }
      // TODO: Implement task deletion
    } catch (err) {
      vscode.window.showErrorMessage(`Failed to delete task: ${err}`);
    }
  }

  public async showAllTasks(): Promise<void> {
    try {
      // TODO: Implement show all tasks in a panel
    } catch (err) {
      vscode.window.showErrorMessage(`Failed to show all tasks: ${err}`);
    }
  }

  public async showTasksByTag(): Promise<void> {
    try {
      // TODO: Implement show tasks by tag
    } catch (err) {
      vscode.window.showErrorMessage(`Failed to show tasks by tag: ${err}`);
    }
  }

  public async runCustomQuery(): Promise<void> {
    try {
      // TODO: Implement custom query dialog
    } catch (err) {
      vscode.window.showErrorMessage(`Failed to run custom query: ${err}`);
    }
  }
}

import initHelpButton from './initHelpButton';
import initSongSelector from './initSongSelector';
import initWaveformSelector from './initWaveformSelector';
import './style.css'

type ValidFFTSizeStringType = '2048' | '1024' | '512';

const audioElement = document.querySelector('audio');
const html = document.querySelector('html');
const canvas = document.querySelector('canvas');
const overlayControls = document.querySelector('.overlay-controls');
const canvasContext = canvas?.getContext('2d');
const FFT_SIZE_TO_RADIUS_MAP = {
  '2048': Math.floor(((2048 / 2) / Math.PI) - 80),
  '1024': Math.floor(((1024 / 2) / Math.PI) - 80),
  '512': Math.floor(((512 / 2) / Math.PI) - 80)
};
const FFT_SIZE_TO_WAVE_HEIGHT_MAP = {
  '2048': 0.5,
  '1024': 0.4,
  '512': 0.3
}
const MIN_FFT_SIZE = 512;

let WIDTH = 1280;
let HEIGHT = 320;
let FFT_SIZE = 2048;
let isNotAPlayPauseTouch = false;
let currentAudioURL = '';
let currentWaveform = 'sinewave'
let previousTouch: (undefined | Touch);
let audioContext: (undefined | null | AudioContext),
  gainNode: (undefined | GainNode),
  mediaElementNode: (undefined | MediaElementAudioSourceNode),
  analyserNode: (undefined | AnalyserNode),
  animationCancelId: (undefined | number);

if (audioElement) {
  audioElement.src = currentAudioURL;
}

/* SETUP */
const setupAudioContext = () => {

  if (!audioElement) {
    return null;
  }

  audioContext = new AudioContext();
  mediaElementNode = audioContext.createMediaElementSource(audioElement);
  gainNode = audioContext.createGain();
  analyserNode = audioContext.createAnalyser();

  gainNode.gain.value = 1;

  if (audioContext.state === 'suspended') {
    audioContext.resume();
  }

  // Do not forget to connect the node to a destination
  mediaElementNode.connect(analyserNode);
  analyserNode.connect(gainNode);
  gainNode.connect(audioContext.destination);
};

/* ANIMATION OPERATIONS */

const drawSineWave = () => {
  if (!analyserNode || !canvas || !canvasContext) {
    return;
  }

  animationCancelId = requestAnimationFrame(drawSineWave);

  analyserNode.fftSize = FFT_SIZE;
  const byteTimeDomainData = new Uint8Array(analyserNode.fftSize);
  analyserNode.getByteTimeDomainData(byteTimeDomainData);

  canvasContext.fillStyle = 'black';
  canvasContext.fillRect(0, 0, WIDTH, HEIGHT);
  canvasContext.strokeStyle = 'white';

  const xAxisSeparation = WIDTH / (analyserNode.fftSize);
  const START_Y = HEIGHT / 2 + 128;

  canvasContext.beginPath();
  // canvasContext.moveTo(0, START_Y);

  byteTimeDomainData.forEach((value, index) => {
    const x = index * xAxisSeparation;
    const y = START_Y - value;

    canvasContext.lineTo(x, y);
  });

  canvasContext.stroke();
};

// Parts of this code are Adapted from standard coding samples
// Specifically the logic to calculate the angle inside the for loop
// was AI generated. I was trying to use the Mid point circle algorithm
// but the AI used trigonometric method (this is supposed to be slower
// but I was blocked in my approach).
const drawCircle = () => {
  if (!canvas || !canvasContext || !analyserNode) {
    return;
  }

  animationCancelId = requestAnimationFrame(drawCircle);

  const numPoints = FFT_SIZE;
  const centerX = canvas.width / 2;
  const centerY = canvas.height / 2;
  const radius = FFT_SIZE_TO_RADIUS_MAP[('' + numPoints) as ValidFFTSizeStringType];
  const points = [];

  // Clear the screen for the current animation frame
  canvasContext.fillStyle = 'black';
  canvasContext.fillRect(0, 0, canvas.width, canvas.height);

  // Set the stroke style
  canvasContext.strokeStyle = 'white';

  analyserNode.fftSize = FFT_SIZE;
  const byteTimeDomainData = new Uint8Array(analyserNode.fftSize);
  analyserNode.getByteTimeDomainData(byteTimeDomainData);

  for (let i = 0; i < numPoints; i++) {
    // Calculating the angle of a given point by using formula:
    // (index/total) * 360
    // When index/total is 1 i.e index === total, then angle will be
    // 360 degrees.
    let angle = (i / numPoints) * 2 * Math.PI;

    // x = r * cos(theta)
    // Adding byteTimeDomainData[i] to r because we want the point to
    // represent the amplitude of the wave.
    let x = centerX + (radius + byteTimeDomainData[i]) * Math.cos(angle);
    // y = r * sin(theta)
    let y = centerY + (radius + byteTimeDomainData[i]) * Math.sin(angle);

    // Store the points in an array for later access
    points.push({x: x, y: y});
  }

  canvasContext.beginPath();
  for (let i = 0; i < points.length; i++) {
    canvasContext.lineTo(points[i].x, points[i].y);
  }
  canvasContext.stroke();
}

/* AUDIO OPERATIONS */

const playPauseAudio = () => {
  if (!audioElement) {
    return;
  }

  if (!audioContext) {
    setupAudioContext();
  }

  if (audioElement.paused) {
    audioElement.play();
    currentWaveform === 'sinewave' ? drawSineWave() : drawCircle();
  }
  else {
    audioElement.pause();
    animationCancelId !== undefined && cancelAnimationFrame(animationCancelId);
  }
}

const increaseVolume = (delta = 0.1) => {
  const gain = gainNode?.gain;

  if (gain === undefined) {
    return;
  }

  const newValue = gain.value + delta;
  (newValue < 2) && (gain.value = newValue);
}

const decreaseVolume = (delta = 0.1) => {
  const gain = gainNode?.gain;

  if (gain === undefined) {
    return;
  }

  const newValue = gain.value - delta;
  (newValue > 0) && (gain.value = newValue);
}

/* RESIZE HANDLER */
const resizeObserver = new ResizeObserver((entries) => {
  for (let entry of entries) {
    if (entry.borderBoxSize) {
      WIDTH = entry.borderBoxSize[0].inlineSize;
      HEIGHT = entry.borderBoxSize[0].blockSize;

      if (canvas && canvasContext) {
        canvas.width = WIDTH;
        canvas.height = HEIGHT;

        canvasContext.fillStyle = "black";
        canvasContext.fillRect(0, 0, canvas.width, canvas.height);
      }

      const bestFFTSizeBasedOnWidth = Object.entries(FFT_SIZE_TO_RADIUS_MAP).sort((a, b) => b[1] - a[1]).find(([key, value]) => {
        // @ts-ignore
        return 2 * (value + FFT_SIZE_TO_WAVE_HEIGHT_MAP[key] * 500) < WIDTH
      });

      console.log(bestFFTSizeBasedOnWidth)
      FFT_SIZE = bestFFTSizeBasedOnWidth ? Number.parseInt(bestFFTSizeBasedOnWidth[0]) : MIN_FFT_SIZE;

      currentWaveform === 'sinewave' ? drawSineWave() : drawCircle();

      return;
    }
  }
});


/* EVENT HANDLERS */
const handleKeyDown = (e: KeyboardEvent) => {
  const { key } = e;

  if (!audioContext && !(e.metaKey || e.altKey || e.ctrlKey)) {
    setupAudioContext();
  }

  switch (key) {
    case ' ': {
      playPauseAudio();
      break;
    }

    case 'ArrowUp': {
      increaseVolume();
      break;
    }

    case 'ArrowDown': {
      decreaseVolume();
      break;
    }
  }
}

const handleTouchEnd = () => {
  if (isNotAPlayPauseTouch) {

    // Cleanup
    isNotAPlayPauseTouch = false;
    previousTouch = undefined;
    return;
  }

  playPauseAudio();
}

const handleTouchMove = (e: TouchEvent) => {
  // This is a touch move and not just a touch.
  // i.e. the user wants to increase or decrease their volume.
  // Setting isNotAPlayPauseTouch will ensure that the music does not
  // stop/start playing.
  isNotAPlayPauseTouch = true;

  // There was no previous touch
  // The user has not indicated whether they want to increase or decrease
  // volume. So, we retun.
  if (!previousTouch) {
    return;
  }

  const currentTouch = e.changedTouches[0];

  if (currentTouch.clientY > previousTouch.clientY) {
    decreaseVolume();
  }
  else {
    increaseVolume();
  }

  previousTouch = currentTouch;
}

const handleTouchStart = (e: TouchEvent) => {
  previousTouch = e.changedTouches[0];
}

const songSelectorCallback = (url: string) => {
  if (!audioElement) {
    return;
  }

  audioElement.src = url;
  playPauseAudio();
}

const waveformSelectorCallback = (option: string) => {
  if (!audioElement) {
    return;
  }

  currentWaveform = option;

  typeof animationCancelId === 'number'  && cancelAnimationFrame(animationCancelId);

  currentWaveform === 'sinewave' ? drawSineWave() : drawCircle();
}

/* INITIALIZE OTHER UI ELEMENTS */
initSongSelector(songSelectorCallback);
initWaveformSelector(waveformSelectorCallback);
initHelpButton();

/* REGISTER EVENT LISTENERS */
window.addEventListener('keydown', handleKeyDown);
window.addEventListener('touchstart', handleTouchStart);
window.addEventListener('touchend', handleTouchEnd);
window.addEventListener('touchmove', handleTouchMove);
overlayControls && overlayControls.addEventListener('touchend', (e) => { e.stopPropagation(); });
overlayControls && overlayControls.addEventListener('touchmove', (e) => { e.stopPropagation(); });
resizeObserver.observe(html as HTMLHtmlElement);

