/*BroadcateR rewrote in TypeScript */

/* Software beneath is wrote with help of Github Copilot as i'm new to TypeScript :) */
/* You're free to modify, fork, commit, add functionality and profit of it as long as you mention my github Lukseh or my website Lukseh.org */

import fs_p from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import http from 'node:http';
import JSON5 from 'json5';
import express, { Request, Response, NextFunction } from 'express';
import { WebSocketServer, WebSocket } from 'ws';
import { renderBroadcastPage, renderMainDashboard } from './renderer.js';
import { Instance, GSISnapshot, AuthRequest } from './types.js';

/* Constants and Environment */
const __dirname = path.dirname(fileURLToPath(import.meta.url));
const PORT: number = Number(process.env.PORT) || 8740;
const BASE_PATH: string = (process.env.BASE_PATH || '/broadcast').replace(/\/+$/, '');
const AUTH_KEY: string = process.env.AUTH_KEY || 'super-secret-key';

/* Instance Configuration */
const instanceRaw: string = await fs_p.readFile(path.join(__dirname, '..', 'instances.json5'), 'utf8');
const { instances = [] }: { instances: Instance[] } = JSON5.parse(instanceRaw);

/* Express Setup */
const app = express();
app.use('/assets', express.static(path.join(__dirname, '..', 'assets')));
app.use(express.json());

/* Enhanced Authentication Middleware */
function protect(req: AuthRequest, res: Response, next: NextFunction): void {
  const key = req.get('x-auth-key') || 
              req.query.key as string || 
              req.body?.auth?.token;

  if (key === AUTH_KEY) {
    return next();
  }

  console.warn(`Unauthorized access attempt from ${req.ip} at ${new Date().toISOString()}`);
  res.status(401).json({ 
    error: 'unauthorized',
    message: 'Valid API key required',
    timestamp: new Date().toISOString()
  });
}

/* History Buffer with Improved Types */
const history: Record<string, GSISnapshot[]> = Object.create(null);

/* Helper: Purge old items to prevent memory leaks */
function purgeOld(arr: GSISnapshot[], delayMs: number): void {
  const limit = Date.now() - delayMs * 3;
  while (arr.length && arr[0].ts < limit) {
    arr.shift();
  }
}

/* WebSocket Management */
const wss = new WebSocketServer({ noServer: true });
const wsClients: Record<string, Set<WebSocket>> = Object.create(null);

/* Broadcast delayed GSI data to WebSocket clients */
function broadcastDelayedGSI(instanceId: string, delayMs: number): void {
  const clients = wsClients[instanceId];
  if (!clients) return;

  const snapshots = history[instanceId] || [];
  const cutoff = Date.now() - delayMs;

  // Find the most recent snapshot that's old enough (past the delay)
  let delayedSnapshot: any = null;
  for (let i = snapshots.length - 1; i >= 0; i--) {
    if (snapshots[i].ts <= cutoff) {
      delayedSnapshot = snapshots[i].data;
      break;
    }
  }

  if (!delayedSnapshot) return;

  // Remove auth data before broadcasting
  const cleanData = { ...delayedSnapshot };
  if (cleanData.auth) delete cleanData.auth;

  // Broadcast to all connected clients
  for (const client of clients) {
    if (client.readyState === WebSocket.OPEN) {
      try {
        client.send(JSON.stringify(cleanData));
      } catch (error) {
        console.error(`WebSocket send error for instance ${instanceId}:`, error);
      }
    }
  }
}

/* Main Dashboard Route */
app.get('/', (req: Request, res: Response) => {
  res.type('html').send(renderMainDashboard(instances));
});

/* Route Setup for Each Instance */
for (const instance of instances) {
  // Normalize instance properties
  instance.url = `/${String(instance.url || instance.id)}`.replace(/\/+/g, '/');
  instance.delay_ms = Number(instance.delay_ms) || 8000; // Default 8 seconds

  const overlayRoute = BASE_PATH + instance.url;
  const gsiRoute = '/gsi' + instance.url;
  const wsRoute = '/ws' + instance.url;

  // Broadcast page route
  app.get(overlayRoute, (req: Request, res: Response) => {
    res.type('html').send(renderBroadcastPage(instance, instances));
  });

  // GET: Retrieve delayed GSI snapshot (public, no auth needed)
  app.get(gsiRoute, (req: Request, res: Response) => {
    const snapshots = history[instance.id] || [];
    const cutoff = Date.now() - instance.delay_ms!;

    let delayedSnapshot: any = null;
    for (let i = snapshots.length - 1; i >= 0; i--) {
      if (snapshots[i].ts <= cutoff) {
        delayedSnapshot = snapshots[i].data;
        break;
      }
    }

    // Always remove auth data from response
    if (delayedSnapshot && delayedSnapshot.auth) {
      delayedSnapshot = { ...delayedSnapshot };
      delete delayedSnapshot.auth;
    }

    res.json(delayedSnapshot || {});
  });

  // POST: Store new GSI data (requires authentication)
  app.post(gsiRoute, protect, (req: AuthRequest, res: Response) => {
    const snapshots = history[instance.id] ||= [];

    // Clean the data before storing (never store auth keys)
    const cleanData = { ...req.body };
    if (cleanData.auth) delete cleanData.auth;

    const snapshot: GSISnapshot = {
      ts: Date.now(),
      data: cleanData
    };

    snapshots.push(snapshot);
    purgeOld(snapshots, instance.delay_ms!);

    // Broadcast the delayed snapshot to WebSocket clients
    broadcastDelayedGSI(instance.id, instance.delay_ms!);

    res.json({ 
      ok: true, 
      stored: snapshots.length,
      instance: instance.id,
      delay_ms: instance.delay_ms,
      timestamp: snapshot.ts
    });
  });

  // WebSocket upgrade placeholder
  app.get(wsRoute, (req: Request, res: Response) => {
    res.status(426).json({
      error: 'Upgrade Required',
      message: 'This endpoint requires WebSocket upgrade'
    });
  });

  console.log(`Instance: ${instance.id}`);
  console.log(`  Broadcast: GET  ${overlayRoute}`);
  console.log(`  GSI:       GET  ${gsiRoute} (delayed by ${instance.delay_ms}ms)`);
  console.log(`  GSI:       POST ${gsiRoute} (auth required)`);
  console.log(`  WebSocket:      ${wsRoute}`);
}

/* HTTP Server with WebSocket Upgrade */
const server = http.createServer(app);

server.on('upgrade', (req, socket, head): void => {
  const url = req.url;
  if (!url) {
    socket.destroy();
    return;
  }

  const matchedInstance = instances.find(inst => `/ws${inst.url}` === url);
  if (!matchedInstance) {
    socket.destroy();
    return;
  }

  const instanceId = matchedInstance.id;

  wss.handleUpgrade(req, socket, head, (ws: WebSocket) => {
    // Initialize client set if needed
    if (!wsClients[instanceId]) {
      wsClients[instanceId] = new Set();
    }

    wsClients[instanceId].add(ws);
    console.log(`WebSocket connected to instance ${instanceId}`);

    ws.on('close', () => {
      wsClients[instanceId]?.delete(ws);
      console.log(`WebSocket disconnected from instance ${instanceId}`);
    });

    ws.on('error', (error) => {
      console.error(`WebSocket error for instance ${instanceId}:`, error);
      wsClients[instanceId]?.delete(ws);
    });
  });
});

/* Start Server */
server.listen(PORT, () => {
  console.log(`=================================`);
  console.log(`🚀 BroadcasteR.ts Server Started`);
  console.log(`📡 Server: http://localhost:${PORT}`);
  console.log(`🔐 Auth: ${AUTH_KEY ? '[CONFIGURED]' : '[WARNING: DEFAULT KEY]'}`);
  console.log(`📂 Base Path: ${BASE_PATH}`);
  console.log(`📊 Instances: ${instances.length}`);
  console.log(`=================================`);
});

/* 404 Handler */
app.use((req: Request, res: Response) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path,
    timestamp: new Date().toISOString()
  });
});

// Aided with basic GitHub coding tools
import { defaultGridConfig, type GridConfig } from '../config/gridConfig';
import { Tile } from './Tile';
import type { GameState, TileGenerator } from './TileGenerator';

export class Grid {
    private readonly _tiles: (Tile | null)[][];

    constructor(
        private readonly width: number,
        private readonly height: number,
        private readonly config: GridConfig = defaultGridConfig
    ) {
        this.validateDimensions(width, height);
        this._tiles = Array(height).fill(null).map(() => 
            Array(width).fill(null)
        );
    }

    private validateDimensions(width: number, height: number): void {
        if (!Number.isInteger(width) || !Number.isInteger(height)) {
            throw new Error('Grid dimensions must be integers');
        }
        if (width < this.config.minWidth || width > this.config.maxWidth) {
            throw new Error(`Width must be between ${this.config.minWidth} and ${this.config.maxWidth}`);
        }
        if (height < this.config.minHeight || height > this.config.maxHeight) {
            throw new Error(`Height must be between ${this.config.minHeight} and ${this.config.maxHeight}`);
        }
    }

    get tiles(): ReadonlyArray<ReadonlyArray<Tile | null>> {
        return this._tiles;
    }

    get dimensions(): readonly [number, number] {
        return [this.width, this.height];
    }

    clone(): Grid {
        const newGrid = new Grid(this.width, this.height, this.config);
        for (let y = 0; y < this.height; y++) {
            for (let x = 0; x < this.width; x++) {
                const tile = this._tiles[y][x];
                newGrid._tiles[y][x] = tile ? tile.clone() : null;
            }
        }
        return newGrid;
    }

    populateGrid(generator: TileGenerator, initialState: GameState): void {
        let state: GameState = { ...initialState };

        for (let y = 0; y < this.height; y++) {
            for (let x = 0; x < this.width; x++) {
                const tile = generator.generateTile(state);
                this._tiles[y][x] = tile;
                // Update state with last generated value for next iteration
                state = { ...state, lastGeneratedValue: tile.value };
            }
        }
    }
}

import { AxiosResponse } from 'axios';
import { readJson, writeFile, writeJson } from 'fs-extra';
import { EOL } from 'os';
import * as path from 'path';
import * as semver from 'semver';
import { EachApiCallNextApiUrlParser, EachApiCallOptions, eachApiCalls } from './utils';


// Interfaces
interface GithubIssue {
    id: string;
    url: string;
    html_url: string;
    number: number;
    state: 'open' | 'closed';
    labels: {
        id: number;
        name: string;
    }[];
    title: string;
    body: string;
    user: {
        login: string;
        url: string;
        avatar_url: string;
        html_url: string;
        type: 'User';
    };
    milestone?: {
        id: string;
        number: number;
        title: string;
        description: string;
        open_issues: number;
        closed_issues: number;
        created_at: string;
        closed_at: string | null;
        due_on: string;
    };
    pull_request?: {
        url: string;
        html_url: string;
    };
    closed_at: string | null;
    created_at: string;
}


type IssueType = 'feature' | 'enhancement' | 'bug' | 'doc' | 'art';
const allIssueTypes: IssueType[] = ['feature', 'enhancement', 'bug', 'doc', 'art'];
const issueTypeEmojiMap = {
    feature: '💡',
    enhancement: '🛠',
    bug: '🔥',
    doc: '📖',
    art: '🎨',
};


interface ChangelogItem {
    types?: IssueType[];
    title: string;
    number: number;
    htmlUrl: string;
}


interface ChangelogOfVersion {
    version: string;
    items: ChangelogItem[];
}


// General functions
const githubNextApiUrlParser: EachApiCallNextApiUrlParser =
    (response: AxiosResponse): string | null => {
        const linkHeader = response.headers.link;

        if (!linkHeader) {
            return null;
        }

        // 'Pages' header values like "<https://some-next-url> rel=next, <https://some-prev-url> rel=prev".
        const pages = (linkHeader as string).split(',');

        if (pages[0] && /rel="next"/.test(pages[0])) {
            const matches = pages[0].match(/<(.+)>/);

            if (matches && matches[1]) {
                return matches[1];
            } else {
                return null;
            }
        }

        return null;
    };


// Application functions
async function getAllPullRequestsForMilestone(milestone: string): Promise<GithubIssue[]> {
    const issues: GithubIssue[] = [];
    const options: EachApiCallOptions = {
        requestConfig: {
            params: {
                state: 'closed',
                milestone,
            },
            headers: {
                Accept: 'application/vnd.github.v3+json',
                'User-Agent': 'geeks-diary',
            },
        },
        nextApiUrlParser: githubNextApiUrlParser,
    };

    if (process.env.GITHUB_USER && process.env.GITHUB_PASSWORD) {
        options.requestConfig.auth = {
            username: process.env.GITHUB_USER,
            password: process.env.GITHUB_PASSWORD,
        };
    }

    const eachGithubIssueApiCalls = eachApiCalls<GithubIssue[]>(
        'https://api.github.com/repos/seokju-na/geeks-diary/issues',
        options,
    );

    for await (const data of eachGithubIssueApiCalls) {
        issues.push(...data);
    }

    return issues.filter(issue => !!issue.pull_request);
}


function parsePrToChangelogItem(pr: GithubIssue): ChangelogItem {
    const types: IssueType[] = pr.labels.reduce(
        (reduced, label) => allIssueTypes.includes(label.name as IssueType)
            ? reduced.concat(label.name as IssueType)
            : reduced,
        [],
    );

    return {
        types,
        title: pr.title,
        number: pr.number,
        htmlUrl: pr.pull_request.html_url,
    };
}


function getChangelogOfVersion(changelogs: ChangelogOfVersion[], version: string): ChangelogOfVersion | undefined {
    const cleanVersion = semver.clean(version);
    return changelogs.find(changelog => changelog.version === cleanVersion);
}


function updateChangelogs(
    changelogs: ChangelogOfVersion[],
    version: string,
    prs: GithubIssue[],
): ChangelogOfVersion[] {
    const prevChangelog = getChangelogOfVersion(changelogs, version);
    const newChangelog: ChangelogOfVersion = {
        version: semver.clean(version),
        items: prs.map(parsePrToChangelogItem),
    };

    if (prevChangelog) {
        const index = changelogs.indexOf(prevChangelog);

        changelogs[index] = newChangelog;
    } else {
        changelogs.push(newChangelog);
    }

    // Sort desc by version.
    return changelogs.sort((a, b) => {
        if (semver.gt(a.version, b.version)) {
            return -1;
        } else if (semver.lt(a.version, b.version)) {
            return 1;
        } else {
            return 0;
        }
    });
}


function getMarkdownFromChangelogs(changelogs: ChangelogOfVersion[]): string {
    let content = `# Changelog${EOL}${EOL}`;

    content += `(💡=Feature, 🛠=Enhancement, 🔥=Bug, 📖=Document, 🎨=Art)${EOL}${EOL}`;

    for (const changelog of changelogs) {
        content += `## v${changelog.version}${EOL}`;

        for (const item of changelog.items) {
            const link = `[#${item.number}](${item.htmlUrl})`;
            const labels = item.types.reduce((typeStr, type) => typeStr + issueTypeEmojiMap[type], '');

            content += labels
                ? `- ${link} ${labels} ${item.title}`
                : `- ${link} ${item.title}`;

            content += EOL;
        }
    }

    return content;
}


// Main function
async function main(version: string, milestone: string): Promise<void> {
    if (!milestone) {
        throw new Error('You should input \'milestone\'.');
    }

    const prs = await getAllPullRequestsForMilestone(milestone);

    // Read changelogs and update
    const CHANGELOGS_JSON_FILE = path.resolve(__dirname, '../changelogs.json');
    let changelogs: ChangelogOfVersion[] = await readJson(CHANGELOGS_JSON_FILE, { throws: true });

    changelogs = updateChangelogs(changelogs, version, prs);

    await writeJson(CHANGELOGS_JSON_FILE, changelogs);

    // Write changelog markdown.
    const CHANGELOG_MARKDOWN_FILE = path.resolve(__dirname, '../CHANGELOG.md');
    const content = getMarkdownFromChangelogs(changelogs);

    await writeFile(CHANGELOG_MARKDOWN_FILE, content);
}


const appVersion = (require('../src/package.json') as any).version;

main(appVersion, process.argv[2])
    .then(() => process.exit(0))
    .catch((error) => {
        console.error(error);
        process.exit(1);
    });

import { Scenario } from "../Scenario.js";
import { Channel, Client, EmbedBuilder, User } from "discord.js";
import Lt from "long-timeout";
import { off } from "process";

export interface ShowOrMovie extends PollItem {}

const hoursToMs = 3600000;

function msToDurationString(durationMS: number): string {

	let durationSecs = durationMS / 1000;

	let days = Math.floor(durationSecs / (24 * 60 * 60));
	durationSecs = durationSecs % (24 * 60 * 60);

	let hours = Math.floor(durationSecs / (60 * 60));
	durationSecs = durationSecs % (60 * 60);

	let minutes = Math.floor(durationSecs / 60);
	let seconds = Math.floor(durationSecs % 60);

	return `${days > 0 	? days + "d " 		: ""}`
		+ `${hours > 0 		? hours + "h " 		: ""}`
		+ `${minutes > 0 	? minutes + "m " 	: ""}`
		+ `${seconds > 0 	? seconds + "s " 	: ""}`;
}

export interface PollItem {
	uid: string;
	name: string,
	img_url: string,
	url: string
}

interface InternalItem<ItemType> {
	nominator: string,
	item: ItemType
}

