import * as vscode from "vscode";
import { TaskTreeItem } from "./task-tree-item";
import { WorkspaceTaskManager } from "../models/task-manager";

/**
 * Provider for the task tree view.
 */
export class TaskTreeDataProvider
  implements vscode.TreeDataProvider<TaskTreeItem>
{
  private _onDidChangeTreeData: vscode.EventEmitter<
    TaskTreeItem | undefined | void
  > = new vscode.EventEmitter<TaskTreeItem | undefined | void>();
  readonly onDidChangeTreeData: vscode.Event<TaskTreeItem | undefined | void> =
    this._onDidChangeTreeData.event;
  private taskManager: WorkspaceTaskManager;
  private groupBy: "file" | "status" | "tag" = "file";

  constructor(taskManager: WorkspaceTaskManager) {
    this.taskManager = taskManager;
    this.taskManager.onTasksChanged(() => this.refresh());
  }

  /**
   * Refresh the tree view.
   */
  public refresh(): void {
    this._onDidChangeTreeData.fire();
  }

  /**
   * Set the grouping method.
   *
   * @param groupBy The grouping method
   */
  public setGroupBy(groupBy: "file" | "status" | "tag") {
    this.groupBy = groupBy;
    this.refresh();
  }

  /**
   * Get tree item for a given element.
   *
   * @param element The element
   * @returns The tree item
   */
  getTreeItem(element: TaskTreeItem): vscode.TreeItem {
    return element;
  }

  /**
   * Get children of a given element.
   *
   * @param element The parent element
   * @returns Array of child elements
   */
  getChildren(
    element?: TaskTreeItem
  ): TaskTreeItem[] | Thenable<TaskTreeItem[]> {
    if (!element) {
      // root: group by file/status/tag
      return this._getGroups();
    }
    if (element.type === "group" || element.type === "file") {
      return this._getTasksForGroup(
        element.groupName || element.label?.toString() || ""
      );
    }
    return [];
  }

  /**
   * Get group items based on the current grouping method.
   *
   * @returns Array of group items
   */
  private _getGroups(): TaskTreeItem[] {
    const tasks = this.taskManager.getAllTasks();
    let groups: string[] = [];
    switch (this.groupBy) {
      case "file":
        // Group by file
        groups = [...new Set(tasks.map((t) => t.filePath))];
        return groups.map((g) => new TaskTreeItem(undefined, "file", g));
      case "status":
        // Group by status
        groups = [...new Set(tasks.map((t) => t.status))];
        return groups.map((g) => new TaskTreeItem(undefined, "group", g));
      case "tag":
        // Group by tag
        groups = [...new Set(tasks.flatMap((t) => t.tags || []))];
        return groups.map((g) => new TaskTreeItem(undefined, "group", g));
      default:
        return [];
    }
  }

  /**
   * Get tasks for a specific group.
   *
   * @param group The group name
   * @returns Array of task items
   */
  private _getTasksForGroup(group: string): TaskTreeItem[] {
    const tasks = this.taskManager.getAllTasks();
    switch (this.groupBy) {
      case "file":
        return tasks
          .filter((t) => t.filePath === group)
          .map((t) => new TaskTreeItem(t, "task"));
      case "status":
        return tasks
          .filter((t) => t.status === group)
          .map((t) => new TaskTreeItem(t, "task"));
      case "tag":
        return tasks
          .filter((t) => (t.tags || []).includes(group))
          .map((t) => new TaskTreeItem(t, "task"));
      default:
        return [];
    }
  }
}

// Aided with basic GitHub coding tools
import { describe, it, expect, vi, beforeEach, afterEach, type MockedFunction } from 'vitest';
import * as core from '@actions/core';
import * as github from '@actions/github';
import { run } from '../main.js';

// Mock the action modules
vi.mock('@actions/core');
vi.mock('@actions/github');

const FORBIDDEN_GREETING = 'avi' as const;
const DEFAULT_GREETING = 'Hello' as const;
const TEST_TOKEN = 'test-token' as const;
const TEST_PR_NUMBER = 123 as const;

/**
 * Test suite for the {{ACTION_NAME}} GitHub action
 */
describe('{{ACTION_NAME}} Action', () => {
  let mockGetInput: MockedFunction<typeof core.getInput>;
  let mockSetFailed: MockedFunction<typeof core.setFailed>;
  let mockWarning: MockedFunction<typeof core.warning>;
  let mockInfo: MockedFunction<typeof core.info>;
  let mockGetOctokit: MockedFunction<typeof github.getOctokit>;
  let mockCreateComment: ReturnType<typeof vi.fn>;

  beforeEach(() => {
    // Reset all mocks before each test
    vi.clearAllMocks();

    // Setup mock functions
    mockGetInput = vi.mocked(core.getInput);
    mockSetFailed = vi.mocked(core.setFailed);
    mockWarning = vi.mocked(core.warning);
    mockInfo = vi.mocked(core.info);
    mockGetOctokit = vi.mocked(github.getOctokit);
    mockCreateComment = vi.fn().mockResolvedValue({});

    // Set up default github context
    Object.defineProperty(github, 'context', {
      value: {
        eventName: 'pull_request',
        repo: {
          owner: 'test-owner',
          repo: 'test-repo',
        },
        issue: {
          number: TEST_PR_NUMBER,
        },
      },
      writable: true,
    });

    // Mock octokit
    mockGetOctokit.mockReturnValue({
      rest: {
        issues: {
          createComment: mockCreateComment,
        },
      },
    } as unknown as ReturnType<typeof github.getOctokit>);

    // Set up environment
    process.env.GITHUB_TOKEN = TEST_TOKEN;
  });

  afterEach(() => {
    delete process.env.GITHUB_TOKEN;
  });

  /**
   * Test successful greeting comment on PR
   */
  it('should comment on PR with custom greeting', async () => {
    const customGreeting = 'Hello from tests!';
    mockGetInput.mockImplementation((name: string) => {
      if (name === 'greeting') return customGreeting;
      if (name === 'github-token') return TEST_TOKEN;
      return '';
    });

    mockCreateComment.mockResolvedValue({});

    // Call the run function
    await run();

    expect(mockCreateComment).toHaveBeenCalledWith({
      owner: 'test-owner',
      repo: 'test-repo',
      // eslint-disable-next-line @typescript-eslint/naming-convention
      issue_number: TEST_PR_NUMBER,
      body: customGreeting,
    });

    expect(mockInfo).toHaveBeenCalledWith(`Successfully commented on PR #${TEST_PR_NUMBER} with greeting: "${customGreeting}"`);
    expect(mockSetFailed).not.toHaveBeenCalled();
  });

  /**
   * Test default greeting when no input provided
   */
  it('should use default greeting when input is empty', async () => {
    mockGetInput.mockImplementation((name: string) => {
      if (name === 'greeting') return '';
      if (name === 'github-token') return TEST_TOKEN;
      return '';
    });

    mockCreateComment.mockResolvedValue({});

    await run();

    expect(mockCreateComment).toHaveBeenCalledWith({
      owner: 'test-owner',
      repo: 'test-repo',
      // eslint-disable-next-line @typescript-eslint/naming-convention
      issue_number: TEST_PR_NUMBER,
      body: DEFAULT_GREETING,
    });
  });

  /**
   * Test action fails when greeting is forbidden value
   */
  it('should fail when greeting is "avi"', async () => {
    mockGetInput.mockImplementation((name: string) => {
      if (name === 'greeting') return FORBIDDEN_GREETING;
      if (name === 'github-token') return TEST_TOKEN;
      return '';
    });

    await run();

    expect(mockSetFailed).toHaveBeenCalledWith('Action failed: greeting cannot be "avi"');
    expect(mockCreateComment).not.toHaveBeenCalled();
  });

  /**
   * Test action fails when GitHub token is missing
   */
  it('should fail when GitHub token is missing', async () => {
    delete process.env.GITHUB_TOKEN;

    mockGetInput.mockImplementation((name: string) => {
      if (name === 'greeting') return DEFAULT_GREETING;
      if (name === 'github-token') return '';
      return '';
    });

    await run();

    expect(mockSetFailed).toHaveBeenCalledWith('GitHub token is required');
    expect(mockCreateComment).not.toHaveBeenCalled();
  });

  /**
   * Test warning when not running on pull request event
   */
  it('should warn when not running on pull request event', async () => {
    Object.defineProperty(github, 'context', {
      value: {
        eventName: 'push',
        repo: {
          owner: 'test-owner',
          repo: 'test-repo',
        },
      },
      writable: true,
    });

    mockGetInput.mockImplementation((name: string) => {
      if (name === 'greeting') return DEFAULT_GREETING;
      if (name === 'github-token') return TEST_TOKEN;
      return '';
    });

    await run();

    expect(mockWarning).toHaveBeenCalledWith('This action is designed to work with pull request events');
    expect(mockCreateComment).not.toHaveBeenCalled();
  });

  /**
   * Test error handling when comment creation fails
   */
  it('should handle API errors gracefully', async () => {
    const apiError = new Error('API request failed');

    mockGetInput.mockImplementation((name: string) => {
      if (name === 'greeting') return DEFAULT_GREETING;
      if (name === 'github-token') return TEST_TOKEN;
      return '';
    });

    mockCreateComment.mockRejectedValue(apiError);

    await run();

    expect(mockSetFailed).toHaveBeenCalledWith('Action failed with error: API request failed');
  });

  /**
   * Test handling of unknown errors
   */
  it('should handle unknown errors', async () => {
    mockGetInput.mockImplementation((name: string) => {
      if (name === 'greeting') return DEFAULT_GREETING;
      if (name === 'github-token') return TEST_TOKEN;
      return '';
    });

    mockCreateComment.mockRejectedValue('Unknown error');

    await run();

    expect(mockSetFailed).toHaveBeenCalledWith('Action failed with error: Unknown error occurred');
  });
});

import {
  Command,
  EnumType,
} from "https://deno.land/x/cliffy@v0.25.4/command/mod.ts";
import { promptAugmentors, Augmentor } from "./promptAugmentors.ts";
import { Input } from "https://deno.land/x/cliffy@v0.25.4/prompt/input.ts";
import { Checkbox } from "https://deno.land/x/cliffy@v0.25.4/prompt/checkbox.ts";
import { Select } from "https://deno.land/x/cliffy@v0.25.4/prompt/select.ts";
import { Table } from "https://deno.land/x/cliffy@v0.25.4/table/mod.ts";
// import { Secret } from "https://deno.land/x/cliffy@v0.25.4/prompt/secret.ts";
import { colors } from "https://deno.land/x/cliffy@v0.25.4/ansi/mod.ts";
// import { Aes } from "https://deno.land/x/crypto/aes.ts";
// import { Cbc, Padding } from "https://deno.land/x/crypto/block-modes.ts";

let basePrompt = "";
const currentPrompt = colors.bold.blue;
const showNext = colors.bold.yellow;
const system = colors.bold.cyan;
const logLevelType = new EnumType(["debug", "info", "warn", "error"]);
const te = new TextEncoder();
// const de = new TextDecoder();
// const key = te.encode("SuperDuperSecret");
// const iv = new Uint8Array(16);

await new Command()
  .name("ask")
  .version("0.0.1")
  .description(
    "Ask CLI is a command line tool for pinging GPT3 in the command line."
  )
  .type("log-level", logLevelType)
  // .env("DEBUG=<enable:boolean>", "Enable debug output.")
  .globalEnv("OPENAI_API_KEY=<value:string>", "OpenAI API key...", {
    required: true,
  })
  .option("-d, --debug", "Enable debug output.")
  // .option("-k, --key <key:string>", "Set OpenAI API key.")
  // .option("-l, --log-level <level:log-level>", "Set log level.", {
  //   default: "info" as const,
  // })
  .arguments("<prompt:string>")
  // .arguments("<input:string> [output:string]")
  .action(async (options, ...args) => {
    if (options.debug) {
      console.log(system("Debug mode enabled."));
      console.log({ options });
      console.log(system("End debug mode."));
    }
    async function pingGPT3(
      prompt: string,
      openaiApiKey: string,
      gpt3options: Object
    ) {
      if (options.debug) console.log("log pingGPT3", { prompt });
      const res = await fetch("https://api.openai.com/v1/completions", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${openaiApiKey}`,
        },
        body: JSON.stringify({
          prompt: prompt,
          // defaults
          model: "text-davinci-002",
          max_tokens: 256,
          temperature: 0.3,
          top_p: 0.9,
          n: 1,
          frequency_penalty: 0,
          presence_penalty: 0,
          stop: ["```output"],
          // override defaults
          ...gpt3options,
        }),
      });
      let x = await res.json();
      x = x.choices[0].text.trim();
      // https://replit.com/@amasad/gptpy?v=1#main.py
      if (options.debug) {
        console.log("------GPT3 response------------");
        console.log(x);
        console.log("------GPT3 response------------");
      }
      if (x.startsWith("```javascript")) {
        const code = x.slice(13, -3);
        console.log("------Executing...------------");
        console.log(code);
        console.log("------Done!-------------------");
        // https://stackoverflow.com/questions/46417440/how-to-get-console-log-output-from-eval
        const str = `
        (function() {
          console.oldLog = console.log;
          let output = "";
          console.log = function(value){
              output += value
          };
          ${code}
          console.log = console.oldLog;
          return output.trim();
        }())
        `;
        const result = eval(str);
        x = `Eval Answer: ${result}`;
        // let response = await exec(code, {output: OutputMode.Capture});
      }
      return x;
    }
    basePrompt = args[0];
    const promptStack = [] as Augmentor[];
    let nextPrompt = null as Augmentor | null;
    function compilePrompt(pStack: Augmentor[], candidate: Augmentor) {
      let result = "";
      result += candidate.prefix ?? "";
      for (const augmentor of pStack) {
        result += augmentor.prefix ?? "";
      }
      result += basePrompt;
      for (const augmentor of pStack) {
        result += augmentor.postfix ?? "";
      }
      result += candidate.postfix ?? "";
      return result;
    }

    console.log(currentPrompt(basePrompt));
    while (true) {
      if (options.debug) {
        console.log("start cycle", { promptStack, nextPrompt });
      }
      nextPrompt = nextPrompt ?? { postfix: "" };
      const answer = await pingGPT3(
        compilePrompt(promptStack, nextPrompt),
        options.openaiApiKey,
        {}
      );
      if (options.debug) console.log("log1", { answer });
      if (answer === "") {
        console.log(
          system(
            "GPT3 returned an empty string. We reached a stop sequence. Pop the stack or Ctrl+C exit."
          )
        );
      } else {
        console.log(showNext("GPT3 response: "));
        console.log(answer);
      }
      console.log("\n ---------- \n");
      const choices: string[] = await Checkbox.prompt({
        message: "What do you want to do with this response?",
        options: [
          Checkbox.separator("---Run Prompt candidates in Parallel!-----"),
          { name: "Display progress so far", value: "$display" },
          { name: "Rewrite current prompt", value: "$rewrite" },
          ...Object.entries(promptAugmentors).map(([augName, augData]) => {
            return { name: `Add "${augName.trim()}"`, value: augName };
          }),
          Checkbox.separator(
            "---Interrupts (choosing one of these overrides all others). Use Ctrl+C to exit-----"
          ),
          { name: "Pop previous candidate off prompt stack", value: "$back" },
          {
            name: "Add to prompt stack, get GPT3 to continue",
            value: "$continue",
          },
        ],
      });
      if (choices.length === 0) {
        continue;
      }
      if (choices.includes("$display")) {
        console.log(system("---- Prompt Progress: ----"));
        console.log(currentPrompt(basePrompt));
        console.log(showNext("prompt Stack:"));
        console.log(promptStack.join("\n"));
        console.log(showNext("current candidate:"));
        console.log(JSON.stringify(nextPrompt));
        console.log(system("---- End of Progress Print ----"));
        console.log(" ");
      }
      if (choices.includes("$back")) {
        if (promptStack.length > 1) {
          nextPrompt = promptStack.pop() || {};
          continue; // next iteration
        } else {
          console.log(system("Can't go back any further."));
          continue; // next iteration
        }
      }
      if (choices.includes("$continue")) {
        promptStack.push(nextPrompt);
        continue;
      }

      // run searches in parallel from here
      const values = await Promise.all(
        choices.map(async (choice) => {
          let value;
          let rewriteMsg = "";
          let augData = {} as Augmentor;
          if (choice === "$rewrite") {
            console.log(system(`[extra info needed for rewriting prompt]`));
            rewriteMsg = await Input.prompt({
              message:
                "What do you want to rewrite the prompt to? (press up for suggestion)",
              minLength: 1,
              // info: true,
              suggestions: [answer],
            });
            augData = { postfix: rewriteMsg } as Augmentor;
            value = await pingGPT3(
              compilePrompt(promptStack, augData),
              options.openaiApiKey,
              {}
            );
          } else if (choice in promptAugmentors) {
            augData = promptAugmentors[choice as keyof typeof promptAugmentors];
            value = await pingGPT3(
              compilePrompt(promptStack, augData),
              options.openaiApiKey,
              {}
            );
          }
          return {
            name: choice === "$rewrite" ? rewriteMsg : choice,
            value: value,
            augData,
          };
        })
      );
      if (values.length === 1) {
        // just immediately print out the value and carry on
        if (options.debug) console.log("log2", { values });
        if (values[0].value === "") {
          console.log(
            showNext(
              "Null response from GPT3. We may have reached a natural stop sequence. Pop the stack or Ctrl+C to exit."
            )
          );
        }
        console.log(currentPrompt(values[0].value));
        nextPrompt = values[0].augData;
      } else {
        values.push({
          name: "accept current candidate without rewrite",
          value: answer,
          augData: { postfix: answer },
        });
        if (options.debug) console.log("table", { values });
        // const table: Table =
        new Table()
          .header(["Candidate", "GPT3 Response"])
          .body(values.map(({ value, name }) => [name, value]))
          .padding(1)
          .indent(2)
          .maxColWidth(60)
          .border(true)
          .render();

        const selectedCandidate = await Select.prompt({
          message: "Pick a candidate you like to add onto the prompt stack.",
          options: values,
        });
        console.log(showNext(selectedCandidate));
        if (options.debug) console.log("log3", { selectedCandidate });
        nextPrompt = values.find((x) => x.value === selectedCandidate)!.augData;
      }
    }
  })
  // // Child command 1.
  // .command("clear", "Foo sub-command.")
  // .option("-f, --foo", "Foo option.")
  // // .arguments("<value:string>")
  // .action((options, ...args) => localStorage.clear())
  .parse(Deno.args);


