  if (shouldFind) {
    return vi.fn().mockReturnValue(
      okAsync({
        user: {
          id: "existing-user-id",
          name: "John Doe",
          email: "john@example.com",
        },
        account: {
          account_id: "user123",
          user_id: "existing-user-id",
          provider_id: "auth0",
        },
      }),
