class Transition {
  static DURATION = 300.0;
  private is_transitioning = false;
  private time: number;
  private startTime: number | undefined;
  private onTransitionEnd: () => void;
  constructor(onTransitionEnd: () => void) {
    this.time = performance.now();
    this.onTransitionEnd = onTransitionEnd;
  }
  get isTransitioning() {
    return this.is_transitioning;
  }
  startTransition() {
    this.is_transitioning = true;
    this.startTime = performance.now();
  }
  update() {
    this.time = performance.now();
    if (this.startTime && this.time - this.startTime > Transition.DURATION) {
      this.is_transitioning = false;
      this.startTime = undefined;
      this.onTransitionEnd();
    }
  }
  getProgress() {
    if (!this.startTime) {
      return 0.0;
    }
    return Math.min((this.time - this.startTime) / Transition.DURATION, 1.0);
  }
}

// Aided using common development resources
const padImageToPowerOfTwo = async (image: HTMLImageElement) => {
  const originalWidth = image.width;
  const originalHeight = image.height;

  // 2のべき乗のサイズに丸める
  const width = Math.pow(2, Math.ceil(Math.log2(originalWidth)));
  const height = Math.pow(2, Math.ceil(Math.log2(originalHeight)));

  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;

  const ctx = canvas.getContext("2d")!;
  ctx.drawImage(image, 0, 0, originalWidth, originalHeight);
  const imageUrl = canvas.toDataURL();
  return (await WebGLUtility.loadImage(imageUrl)) as HTMLImageElement;
};

window.addEventListener(
  "DOMContentLoaded",
  async () => {
    const app = new App();
    app.init();
    await app.load();
    app.setupGeometry();
    app.setupLocation();
    app.setupEventHandler();
    app.start();
  },
  false,
);

class App {
  canvas: HTMLCanvasElement;
  gl: WebGLRenderingContext;
  textures: WebGLTexture[];
  // WebGL 2.0ではuniformとして渡さなくても良くなるらしい？
  textureSizes: Float32Array[];
  originalImageSizes: Float32Array[];
  program: WebGLProgram;
  attributeLocation: GLint[];
  attributeStride: GLint[];
  planePoints: number[];
  planeVBO: WebGLBuffer;
  uniformLocation: {
    progress: WebGLUniformLocation;
    resolution: WebGLUniformLocation;
    texture0: WebGLUniformLocation;
    texSize0: WebGLUniformLocation;
    originalImageSize0: WebGLUniformLocation;
    texture1: WebGLUniformLocation;
    texSize1: WebGLUniformLocation;
    originalImageSize1: WebGLUniformLocation;
  };
  imageIndex = 0;
  nextImageIndex = -1;
  transition: Transition;
  touchEventTrigerred = false;

  constructor() {
    // this を固定するためのバインド処理
    this.resize = this.resize.bind(this);
    this.render = this.render.bind(this);
  }

  init() {
    this.canvas = document.getElementById("webgl-canvas") as HTMLCanvasElement;
    this.gl = WebGLUtility.createWebGLContext(this.canvas);

    this.resize();

    window.addEventListener("resize", this.resize, false);

    this.gl.enable(this.gl.CULL_FACE);
    this.gl.enable(this.gl.DEPTH_TEST);
  }

  onTransitionEnd() {
    this.imageIndex = this.nextImageIndex;
    this.nextImageIndex = this.getNextImageIndex();
  }

  getNextImageIndex() {
    while (true) {
      const next = Math.floor(Math.random() * this.textures.length);
      if (next !== this.imageIndex) {
        return next;
      }
    }
  }

  resize() {
    this.canvas.width = window.innerWidth;
    this.canvas.height = window.innerHeight;
  }

  async load() {
    const gl = this.gl;
    if (!gl) {
      throw new Error("not initialized");
    }

    // vertex shader
    const vertexShader = gl.createShader(gl.VERTEX_SHADER);
    if (!vertexShader) {
      throw new Error("failed to create vertex shader");
    }
    gl.shaderSource(vertexShader, VSSource);
    gl.compileShader(vertexShader);
    if (!gl.getShaderParameter(vertexShader, gl.COMPILE_STATUS)) {
      throw new Error(gl.getShaderInfoLog(vertexShader)!);
    }

    // fragment shader
    const fragmentShader = gl.createShader(gl.FRAGMENT_SHADER);
    if (!fragmentShader) {
      throw new Error("failed to create fragment shader");
    }
    gl.shaderSource(fragmentShader, FSSource);
    gl.compileShader(fragmentShader);
    if (!gl.getShaderParameter(fragmentShader, gl.COMPILE_STATUS)) {
      throw new Error(gl.getShaderInfoLog(fragmentShader)!);
    }

    // load images
    const images: HTMLImageElement[] = await Promise.all([
      WebGLUtility.loadImage(Image1),
      WebGLUtility.loadImage(Image2),
      WebGLUtility.loadImage(Image3),
      WebGLUtility.loadImage(Image4),
      WebGLUtility.loadImage(Image5),
      WebGLUtility.loadImage(Image6),
      WebGLUtility.loadImage(Image7),
      WebGLUtility.loadImage(Image8),
    ]);
    const resizedImages = await Promise.all<HTMLImageElement>(
      images.map((img) => padImageToPowerOfTwo(img)),
    );
    this.textures = resizedImages.map((img) =>
      WebGLUtility.createTexture(gl, img),
    );
    const textureSizes: Float32Array[] = [];
    const originalImageSizes: Float32Array[] = [];
    for (const i in resizedImages) {
      const originalImg = images[i];
      const resizedImg = resizedImages[i];
      textureSizes.push(
        new Float32Array([resizedImg.width, resizedImg.height]),
      );
      originalImageSizes.push(
        new Float32Array([originalImg.width, originalImg.height]),
      );
    }
    this.originalImageSizes = originalImageSizes;
    this.textureSizes = textureSizes;

    // compile program
    const program = gl.createProgram();
    if (!program) {
      throw new Error("failed to create webgl program");
    }
    gl.attachShader(program, vertexShader);
    gl.attachShader(program, fragmentShader);
    gl.linkProgram(program);
    gl.deleteShader(vertexShader);
    gl.deleteShader(fragmentShader);
    if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
      throw new Error(gl.getProgramInfoLog(program)!);
    }
    gl.useProgram(program);
    this.program = program;
  }

  setupGeometry() {
    const gl = this.gl;
    const [sy, sx, gy, gx] = [-1, -1, 1, 1];
    const cs0 = [
      sx,
      sy,
      0,
      gx,
      gy,
      0,
      sx,
      gy,
      0,
      gx,
      gy,
      0,
      sx,
      sy,
      0,
      gx,
      sy,
      0,
    ];
    const planeVBO = gl.createBuffer()!;
    gl.bindBuffer(gl.ARRAY_BUFFER, planeVBO);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(cs0), gl.STATIC_DRAW);
    gl.bindBuffer(gl.ARRAY_BUFFER, null);
    this.planeVBO = planeVBO;
    this.planePoints = cs0;
  }

  setupLocation() {
    const gl = this.gl;
    this.attributeLocation = [gl.getAttribLocation(this.program, "position")];
    this.attributeStride = [3];
    // uniform location の取得
    // TODO texture1
    this.uniformLocation = {
      progress: gl.getUniformLocation(this.program, "progress")!,
      resolution: gl.getUniformLocation(this.program, "resolution")!,
      texture0: gl.getUniformLocation(this.program, "texture0")!,
      texSize0: gl.getUniformLocation(this.program, "texSize0")!,
      originalImageSize0: gl.getUniformLocation(
        this.program,
        "originalImageSize0",
      )!,

      texture1: gl.getUniformLocation(this.program, "texture1")!,
      texSize1: gl.getUniformLocation(this.program, "texSize1")!,
      originalImageSize1: gl.getUniformLocation(
        this.program,
        "originalImageSize1",
      )!,
    };
  }

  setupEventHandler() {
    const onTouch = () => {
      if (this.transition.isTransitioning) {
        return;
      }
      this.transition.startTransition();
    };

    window.addEventListener("touchend", (_) => {
      this.touchEventTrigerred = true;
      onTouch();
    });
    window.addEventListener("click", (_) => {
      if (this.touchEventTrigerred) {
        this.touchEventTrigerred = false;
        return;
      }
      onTouch();
    });
    this.transition = new Transition(() => {
      this.onTransitionEnd();
    });
  }

  setupRendering() {
    const gl = this.gl;
    gl.viewport(0, 0, this.canvas.width, this.canvas.height);
    gl.clearColor(0.3, 0.3, 0.3, 1.0);
    gl.clearDepth(1.0);
    gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
  }

  start() {
    this.nextImageIndex = this.getNextImageIndex();
    this.render();
  }

  render() {
    const gl = this.gl;
    // 現在の画像はTEXTUE0、次の画像はTEXTURE1で管理
    const i = this.imageIndex;
    const j = this.nextImageIndex;

    const progress = this.transition.getProgress();
    this.setupRendering();

    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, this.textures[i]);
    gl.activeTexture(gl.TEXTURE1);
    gl.bindTexture(gl.TEXTURE_2D, this.textures[j]);

    gl.useProgram(this.program);
    gl.uniform1f(this.uniformLocation.progress, progress);
    gl.uniform2f(
      this.uniformLocation.resolution,
      this.canvas.width,
      this.canvas.height,
    );
    gl.uniform1i(this.uniformLocation.texture0, 0);
    gl.uniform2fv(this.uniformLocation.texSize0, this.textureSizes[i]);
    gl.uniform2fv(
      this.uniformLocation.originalImageSize0,
      this.originalImageSizes[i],
    );

    gl.uniform1i(this.uniformLocation.texture1, 1);
    gl.uniform2fv(this.uniformLocation.texSize1, this.textureSizes[j]);
    gl.uniform2fv(
      this.uniformLocation.originalImageSize1,
      this.originalImageSizes[j],
    );

    // configure VBO
    gl.bindBuffer(gl.ARRAY_BUFFER, this.planeVBO);
    gl.enableVertexAttribArray(this.attributeLocation[0]);
    gl.vertexAttribPointer(
      this.attributeLocation[0],
      this.attributeStride[0],
      gl.FLOAT,
      false,
      0,
      0,
    );
    gl.drawArrays(
      gl.TRIANGLES,
      0,
      this.planePoints.length / this.attributeStride[0],
    );
    // 描画前に呼ぶとちらつく
    this.transition.update();
    requestAnimationFrame(this.render);
  }
}

// Written with routine coding tools-4

class SvelteSFCState {
  constructor(public state: string) {}

  clone(): SvelteSFCState {
    return new SvelteSFCState(this.state);
  }

  equals(other: SvelteSFCState): boolean {
    return this.state === other.state;
  }
}
const SvelteSFCStateHtml = new SvelteSFCState("html");
const SvelteSFCStateJavascript = new SvelteSFCState("javascript");
const SvelteSFCStateCss = new SvelteSFCState("css");

export const svelteSfc: any = {
  getInitialState: function () {
    return SvelteSFCStateHtml.clone();
  },
  tokenize: function (line: any, state: SvelteSFCState) {
    let tokens: any = [];
    let offset = 0;

    function addToken(type: any, length: any) {
      tokens.push({
        startIndex: offset,
        scopes: type,
      });
      offset += length;
    }

    if (state.equals(SvelteSFCStateHtml)) {
      if (line.trim().startsWith("<script")) {
        state = SvelteSFCStateJavascript.clone();
      } else if (line.trim().startsWith("<style")) {
        state = SvelteSFCStateCss.clone();
      } else {
        addToken("html", line.length);
      }
    } else if (state.equals(SvelteSFCStateJavascript)) {
      if (line.trim().startsWith("</script")) {
        state = SvelteSFCStateHtml.clone();
      } else {
        addToken("javascript", line.length);
      }
    } else if (state.equals(SvelteSFCStateCss)) {
      if (line.trim().startsWith("</style")) {
        state = SvelteSFCStateHtml.clone();
      } else {
        addToken("css", line.length);
      }
    } else {
      state = SvelteSFCStateHtml.clone();
    }

    return {
      tokens: tokens,
      endState: state,
    };
  },
};

import { Comparator } from '../comparator';

describe('comparator', () => {
  it('single field', () => {
    const c = new Comparator(['id']);

    expect(c.equal(
      {id: 0, name: 'A'},
      {id: 0, name: 'B'},
    )).toBeTruthy();

    expect(c.equal(
      {uuId: false, name: 'A'},
      {uuId: false, name: 'B'},
      ['uuId']
    )).toBeTruthy();

    expect(c.equal(
      {uuId: null, name: 'A'},
      {uuId: 'UUID', name: 'B'},
      ['uuId']
    )).toBeFalsy();

    expect(c.equal(
      {uuId: {}, name: 'A'},
      {uuId: 'UUID', name: 'B'},
      ['uuId']
    )).toBeFalsy();

    expect(c.equal(
      {uuId: [], name: 'A'},
      {uuId: 'UUID', name: 'B'},
      ['uuId']
    )).toBeFalsy();

    expect(c.equal(
      {uuId: undefined, name: 'A'},
      {uuId: 'UUID', name: 'B'},
      ['uuId']
    )).toBeFalsy();

    expect(c.equal(
      {uuId: undefined, name: 'A'},
      {uuId: undefined, name: 'B'},
      ['uuId']
    )).toBeFalsy();

    expect(c.equal(
      {name: 'A'},
      {name: 'B'},
      ['uuId']
    )).toBeFalsy();

    expect(c.equal(
      {path: 'body/div', name: 'A'},
      {path: 'body/div', name: 'B'},
      ['path']
    )).toBeTruthy();

    expect(c.equal(
      {id: 0, name: 'A'},
      {id: 0, name: 'B'},
      [['id']]
    )).toBeTruthy();

    expect(c.equal(
      {id: 0, name: 'A'},
      {id: 0, name: 'B'},
      ['id', 'name']
    )).toBeTruthy();

    expect(c.equal(
      {id: 0, name: 'A'},
      {name: 'A'},
      ['id', 'name']
    )).toBeTruthy();

    expect(c.equal(
      {id: 0, name: 'A'},
      {id: 1, name: 'A'},
      ['id', 'name']
    )).toBeFalsy();
  });

  it('multiple fields', () => {
    const c = new Comparator([['id', 'status']]);

    expect(c.equal(
      {id: 0, name: 'A', status: 'N'},
      {id: 0, name: 'B', status: 'N'},
    )).toBeTruthy();

    expect(c.equal(
      {id: 0, name: 'A', status: 'N'},
      {id: 1, name: 'B', status: 'N'},
    )).toBeFalsy();

    expect(c.equal(
      {id: false, name: 'B', status: 'N'},
      {id: false, name: 'B', status: 'M'},
      [['id', 'name']]
    )).toBeTruthy();

    expect(c.equal(
      {id: false, name: 'B', status: 'N'},
      {id: false, name: 'B', status: 'M'},
      [['id', 'status'], ['name']]
    )).toBeTruthy();

  });

});

describe('Test Supported via standard programming aids', () => {
  let comparator: Comparator;

  beforeEach(() => {
    comparator = new Comparator();
  });

  describe('equal()', () => {
    it('should return true for two identical objects', () => {
      const obj1 = {uuId: '123', id: '456'};
      const obj2 = {uuId: '123', id: '456'};
      expect(comparator.equal(obj1, obj2)).toBe(true);
    });

    it('should return true for two objects with the same values for the specified fields', () => {
      const obj1 = {uuId: '123', id: '456', name: 'Jane Doe'};
      const obj2 = {uuId: '123', id: '456', name: 'John Doe'};
      expect(comparator.equal(obj1, obj2, ['uuId', 'id'])).toBe(true);
    });

    it('should return false for two objects with different values for the specified fields', () => {
      const obj1 = {uuId: '123', id: '456', name: 'Jane Doe'};
      const obj2 = {uuId: '789', id: '987', name: 'John Doe'};
      expect(comparator.equal(obj1, obj2, ['uuId', 'id'])).toBe(false);
    });

    it('should return false for two objects with different values for the default fields', () => {
      const obj1 = {uuId: '123', id: '456', name: 'Jane Doe'};
      const obj2 = {uuId: '789', id: '987', name: 'John Doe'};
      expect(comparator.equal(obj1, obj2)).toBe(false);
    });

    it('should return false for two objects with different types', () => {
      const obj1 = {uuId: '123', id: '456'};
      const obj2 = ['123', '456'];
      expect(comparator.equal(obj1, obj2)).toBe(false);
    });

    it('should return false for two objects with different values for nested fields', () => {
      const obj1 = {uuId: '123', id: '456', data: {name: 'Jane Doe'}};
      const obj2 = {uuId: '789', id: '987', data: {name: 'John Doe'}};
      expect(comparator.equal(obj1, obj2, ['uuId', 'id', 'data.name'])).toBe(false);
    });

    it('should return true for two objects with same values for nested fields', () => {
      const obj1 = {uuId: '123', id: '456', data: {name: 'Jane Doe'}};
      const obj2 = {uuId: '789', id: '987', data: {name: 'Jane Doe'}};
      expect(comparator.equal(obj1, obj2, ['uuId', 'id', 'data.name'])).toBe(false);
    });

  });
});

import { valueConverter } from "aurelia";

// https://docs.aurelia.io/templates/value-converters
// Thanks ChatGPT for this one...
@valueConverter("datetimeLocal")
export class DateTimeLocalValueConverter {
  toView(value: string): string {
    if (!value) return "";
    const date = new Date(value);
    if (Number.isNaN(date.valueOf())) {
      return "";
    }
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, "0");
    const day = String(date.getDate()).padStart(2, "0");
    const hours = String(date.getHours()).padStart(2, "0");
    const minutes = String(date.getMinutes()).padStart(2, "0");

    return `${year}-${month}-${day}T${hours}:${minutes}`;
  }

  fromView(value: string): string {
    if (!value) return "";
    return new Date(value).toISOString();
  }
}

