/**
 * Supported by standard GitHub tools.
 */
export default class Tree<T> {
    data: T;
    parent: Tree<T> | null = null;
    readonly children: Tree<T>[] = [];

    constructor(data: T, parent: Tree<T> | null = null) {
        this.data = data;
        this.parent = parent;
    }

    appendChild(child: T | Tree<T>): Tree<T> {
        const tree = child instanceof Tree ? child : new Tree<T>(child, this);
        this.children.push(tree);
        return tree;
    }

    removeChild(tree: Tree<T>): void {
        const index = this.children.indexOf(tree);
        if (index > -1)
            this.children.splice(index, 1);
    }

    traverse(callback: (data: T) => void): void {
        callback(this.data);
        this.children.forEach((child) => child.traverse(callback));
    }

    clear(): void {
        // this.children.forEach((child) => child.clear());
        this.children.length = 0;
    }

    find(data: T): Tree<T> | null {
        if (this.data === data)
            return this;
        for (const child of this.children) {
            const result = child.find(data);
            if (result)
                return result;
        }
        return null;
    }
}

/* Imports: External */
import { HardhatRuntimeEnvironment } from 'hardhat/types'
import { HardhatNetworkProvider } from 'hardhat/internal/hardhat-network/provider/provider'

/**
 * Finds the "base" Ethereum provider of the current hardhat environment.
 *
 * Basically, hardhat uses a system of nested providers where each provider wraps the next and
 * "provides" some extra features. When you're running on top of the "hardhat evm" the bottom of
 * this series of providers is the "HardhatNetworkProvider":
 * https://github.com/nomiclabs/hardhat/blob/master/packages/hardhat-core/src/internal/hardhat-network/provider/provider.ts
 * This object has direct access to the node (provider._node), which in turn has direct access to
 * the ethereumjs-vm instance (provider._node._vm). So it's quite useful to be able to find this
 * object reliably!
 * @param hre hardhat runtime environment to pull the base provider from.
 * @return base hardhat network provider
 */
export const findBaseHardhatProvider = (
  runtime: HardhatRuntimeEnvironment
): HardhatNetworkProvider => {
  // This function is pretty approximate. Haven't spent enough time figuring out if there's a more
  // reliable way to get the base provider. I can imagine a future in which there's some circular
  // references and this function ends up looping. So I'll just preempt this by capping the maximum
  // search depth.
  const maxLoopIterations = 1024
  let currentLoopIterations = 0

  // Search by looking for the internal "_wrapped" variable. Base provider doesn't have this
  // property (at least for now!).
  let provider = runtime.network.provider
  while ((provider as any)._wrapped !== undefined) {
    provider = (provider as any)._wrapped

    // Just throw if we ever end up in (what seems to be) an infinite loop.
    currentLoopIterations += 1
    if (currentLoopIterations > maxLoopIterations) {
      throw new Error(
        `[smock]: unable to find base hardhat provider. are you sure you're running locally?`
      )
    }
  }

  // TODO: Figure out a reliable way to do a type check here. Source for inspiration:
  // https://github.com/nomiclabs/hardhat/blob/master/packages/hardhat-core/src/internal/hardhat-network/provider/provider.ts
  return provider as any
}

import type { Plugin, ResolvedConfig } from 'vite'
import type { CompressionOptions, VitePluginCompression } from './types'
import path from 'path'
import { normalizePath } from 'vite'
import { readAllFile, isRegExp, isFunction } from './utils'
import fs from 'fs-extra'
import chalk from 'chalk'
import zlib from 'zlib'
import Debug from 'debug'

const debug = Debug.debug('vite-plugin-compression')

const extRE = /\.(js|mjs|json|css|html)$/i

const mtimeCache = new Map<string, number>()

export default function (options: VitePluginCompression = {}): Plugin {
  let outputPath: string
  let config: ResolvedConfig

  const emptyPlugin: Plugin = {
    name: 'vite:compression',
  }

  const {
    disable = false,
    filter = extRE,
    verbose = true,
    threshold = 1025,
    compressionOptions = {},
    deleteOriginFile = false,
    // eslint-disable-next-line
    success = () => {},
  } = options

  let { ext = '' } = options
  const { algorithm = 'gzip' } = options

  if (algorithm === 'gzip' && !ext) {
    ext = '.gz'
  }

  if (algorithm === 'brotliCompress' && !ext) {
    ext = '.br'
  }

  if (disable) {
    return emptyPlugin
  }

  debug('plugin options:', options)

  return {
    ...emptyPlugin,
    apply: 'build',
    enforce: 'post',
    configResolved(resolvedConfig) {
      config = resolvedConfig
      outputPath = path.isAbsolute(config.build.outDir)
        ? config.build.outDir
        : path.join(config.root, config.build.outDir)
      debug('resolvedConfig:', resolvedConfig)
    },
    async closeBundle() {
      let files = readAllFile(outputPath) || []
      debug('files:', files)

      if (!files.length) return

      files = filterFiles(files, filter)

      const compressOptions = getCompressionOptions(
        algorithm,
        compressionOptions,
      )

      const compressMap = new Map<
        string,
        { size: number; oldSize: number; cname: string }
      >()

      const handles = files.map(async (filePath: string) => {
        const { mtimeMs, size: oldSize } = await fs.stat(filePath)
        if (mtimeMs <= (mtimeCache.get(filePath) || 0) || oldSize < threshold)
          return

        let content = await fs.readFile(filePath)

        if (deleteOriginFile) {
          fs.remove(filePath)
        }

        try {
          content = await compress(content, algorithm, compressOptions)
        } catch (error) {
          config.logger.error('compress error:' + filePath)
        }
        const size = content.byteLength

        const cname = getOutputFileName(filePath, ext)
        compressMap.set(filePath, {
          size: size / 1024,
          oldSize: oldSize / 1024,
          cname: cname,
        })
        await fs.writeFile(cname, content)

        mtimeCache.set(filePath, Date.now())
      })

      return Promise.all(handles).then(() => {
        if (verbose) {
          handleOutputLogger(config, compressMap, algorithm)
          success()
        }
      })
    },
  }
}

function filterFiles(
  files: string[],
  filter: RegExp | ((file: string) => boolean),
) {
  if (filter) {
    const isRe = isRegExp(filter)
    const isFn = isFunction(filter)
    files = files.filter((file) => {
      if (isRe) {
        return (filter as RegExp).test(file)
      }
      if (isFn) {
        // eslint-disable-next-line
        return (filter as Function)(file)
      }
      return true
    })
  }
  return files
}

/**
 * get common options
 */
function getCompressionOptions(
  algorithm = '',
  compressionOptions: CompressionOptions = {},
) {
  const defaultOptions: {
    [key: string]: Record<string, any>
  } = {
    gzip: {
      level: zlib.constants.Z_BEST_COMPRESSION,
    },
    deflate: {
      level: zlib.constants.Z_BEST_COMPRESSION,
    },
    deflateRaw: {
      level: zlib.constants.Z_BEST_COMPRESSION,
    },
    brotliCompress: {
      params: {
        [zlib.constants.BROTLI_PARAM_QUALITY]:
          zlib.constants.BROTLI_MAX_QUALITY,
        [zlib.constants.BROTLI_PARAM_MODE]: zlib.constants.BROTLI_MODE_TEXT,
      },
    },
  }
  return {
    ...defaultOptions[algorithm],
    ...compressionOptions,
  } as CompressionOptions
}

/**
 * Compression core method
 * @param content
 * @param algorithm
 * @param options
 */
function compress(
  content: Buffer,
  algorithm: 'gzip' | 'brotliCompress' | 'deflate' | 'deflateRaw',
  options: CompressionOptions = {},
) {
  return new Promise<Buffer>((resolve, reject) => {
    // @ts-ignore
    zlib[algorithm](content, options, (err, result) =>
      err ? reject(err) : resolve(result),
    )
  })
}

/**
 * Get the suffix
 * @param filepath
 * @param ext
 */
function getOutputFileName(filepath: string, ext: string) {
  const compressExt = ext.startsWith('.') ? ext : `.${ext}`
  return `${filepath}${compressExt}`
}

// Packed output logic
function handleOutputLogger(
  config: ResolvedConfig,
  compressMap: Map<string, { size: number; oldSize: number; cname: string }>,
  algorithm: string,
) {
  config.logger.info(
    `\n${chalk.cyan('✨ [vite-plugin-compression]:algorithm=' + algorithm)}` +
      ` - compressed file successfully: `,
  )

  const keyLengths = Array.from(compressMap.keys(), (name) => name.length)

  const maxKeyLength = Math.max(...keyLengths)
  compressMap.forEach((value, name) => {
    const { size, oldSize, cname } = value

    const rName = normalizePath(cname).replace(
      normalizePath(`${config.build.outDir}/`),
      '',
    )

    const sizeStr = `${oldSize.toFixed(2)}kb / ${algorithm}: ${size.toFixed(
      2,
    )}kb`

    config.logger.info(
      chalk.dim(path.basename(config.build.outDir) + '/') +
        chalk.blueBright(rName) +
        ' '.repeat(2 + maxKeyLength - name.length) +
        ' ' +
        chalk.dim(sizeStr),
    )
  })
  config.logger.info('\n')
}

/**
 * Custom blocks
 */
//% weight=50 color=#16aeac icon="\u0041"
namespace Andee {

    let bleMsg: string;
    let bleReceive: string;
    let reply_flag: boolean;
    let ble_reply: string;
    let packetBreak: number;

    export class Widget {
        private widgetId: number;
        private widgetType: number;
        private widgetCoordX: number;
        private widgetCoordY: number;
        private widgetWidth: number;
        private widgetHeight: number;
        private widgetColour: number;
        private widgetTitle: string;
        private widgetData: string;
        private widgetUnit: string;

        private widgetInputMode: number;
        private widgetMaxValue: number;
        private widgetMinValue: number;
        private widgetSliderSteps: number;
        private widgetSliderForceUpdate: number;

        private widgetUpdate: number;

        public setId(ID: WidgetId): void {
            this.widgetId = ID + 32;
            this.widgetInputMode = 48;
        }
        public setType(typeW: number): void {
            this.widgetType = typeW;
        }

        public setMinMax(minW: number, maxW: number): void {
            this.widgetMinValue = minW;
            this.widgetMaxValue = maxW;
        }
        public setSliderSteps(sliderSteps: number): void {
            this.widgetSliderSteps = sliderSteps + 32;
        }
        /**
         * Force Widget to update
         */
        //% weight=67
        //% blockId=force_update
        //% block="Force %widget| to update"
        //% advanced=true
        public forceUpdate(): void {
            this.widgetUpdate = 0;
        }
        /**
         * The X coordinate of the top left hand corner of the widget
         * @param x Coordinate X of widget, eg: 5
         */
        //% weight=85
        //% blockId=set_widget_coordX
        //% block="Set Coordinate X of %widget| to %x"
        //% x.min=0 x.max=100
        //% advanced=true
        public setCoordX(x: number): void {
            this.widgetCoordX = x + 32;
        }
        /**
         * The Y coordinate of the top left hand corner of the widget
         * @param y Coordinate Y of widget, eg: 5
         */
        //% weight=83
        //% blockId=set_widget_coordY
        //% block="Set Coordinate Y of %widget| to %y"
        //% y.min=0 y.max=100
        //% advanced=true
        public setCoordY(y: number): void {
            this.widgetCoordY = y + 32;
        }
        /**
         * A width should be specified for each widget
         * @param w Set Widget Width, eg: 50
         */
        //% weight=90
        //% blockId=set_widget_width
        //% block="Set Width of %widget| to %w"
        //% w.min=0 w.max=100
        //% advanced=true
        public setWidth(w: number): void {
            this.widgetWidth = w + 32;
        }
        /**
         * A height should be specified for each widget
         * @param h Set Widget Height, eg: 25
         */
        //% weight=87
        //% blockId=set_widget_height
        //% block="Set Height of %widget| to %h"
        //% h.min=0 h.max=100
        //% advanced=true
        public setHeight(h: number): void {
            this.widgetHeight = h + 32;
        }
        /**
         * Each widget should have a colour
         * @param colour Set Widget Colour, eg: WidgetColour.Red
         */
        //% weight=93
        //% blockId=set_widget_colour
        //% block="Set Colour of %widget| to %colour"
        //% advanced=true
        public setColour(colour: WidgetColour): void {
            this.widgetColour = colour + 32;
        }
        /**
         * Each widget should have a title
         * @param title Set Widget Title, eg: "Title"
         */
        //% weight=98
        //% blockId=set_widget_title
        //% block="Set Title of %widget| to %title"
        //% advanced=true
        public setTitle(title: string): void {
            this.widgetTitle = trimString(title);
        }
        /**
         * Units are optional
         * @param units Set Widget Units, eg: "Units"
         */
        //% weight=96
        //% blockId=set_widget_units
        //% block="Set Units of %widget| to %units"
        //% advanced=true
        public setUnit(units: string): void {
            this.widgetUnit = trimString(units);
        }
        /**
         * This can display data
         * @param data Set Widget Data, eg: "Data"
         */
        //% weight=97
        //% blockId=set_widget_data
        //% block="Set Data of %widget| to %data"
        //% advanced=true
        public setData(data: string): void {
            this.widgetData = trimString(data);
            if (this.widgetType == WidgetTypeInput.Slider) {
                this.widgetSliderForceUpdate = 49;
            }
        }
        /**
         * Keyboard widget has more than 1 input modes
         * @param mode Set Button Mode, eg: KeyboardMode.AlphaNumeric
         */
        //% weight=79
        //% blockId=set_kb_mode
        //% block="Set Keyboard Mode of %widget| to %mode"
        //% advanced=true
        public setKeyboardInputMode(mode: KeyboardMode): void {
            this.widgetInputMode = mode;
        }
        /**
         * Block to remove widgets individually
         * @param widget widget to be removed
         */
        //% weight=10
        //% blockId=Andee_remove
        //% block="Remove Widget%widget"
        //% advanced=true
        public remove(): void {
            bleMsg = String.fromCharCode(UISTART) + "E"/*REMOVE*/ + String.fromCharCode(SEP) +
                String.fromCharCode(this.widgetId) + String.fromCharCode(UIEND);
            bluetooth.uartWriteString(bleMsg);
            bleMsg = "";
        }
        /**
         * Update Block to update widget properties   
         * @param widget Widget Data to send to app 
         */
        //% weight=85
        //% blockId=Andee_widget_update
        //% block="Update Widget%widget"
        public update(): void {
            this.updateLoop(20);
        }
        /**
         * Block to send acknowledgement back to app
         */
        //% weight=10
        //% blockId=Andee_ack
        //% block="Send Ack%widget"
        public ack(): void {
            bleMsg = "";
            bleMsg = String.fromCharCode(UISTART) + "A"/*ACKN*/ + String.fromCharCode(SEP) + String.fromCharCode(this.widgetId) + String.fromCharCode(UIEND);
            bluetooth.uartWriteString(bleMsg);
            bleMsg = "";
        }
        /**
         * Update Block to update widget properties   
         * @param widget Widget Data to send to app 
         * @param loop Number of loops before updating widget, eg: 100
         */
        //% weight=70
        //% blockId=Andee_widget_update_loop
        //% block="Update Widget%widget| every %loop|loops"
        //% advanced=true
        public updateLoop(loop: number): void {            

            if (reply_flag == true) {
                reply_flag = false;
                ble_reply = "";
                ble_reply = bleReceive.substr(4);
                control.raiseEvent((bleReceive.charCodeAt(2) - 32) + 30 /*EVENT_ID_OFFSET*/, 62 /*ANDEE_EVENT_VALUE*/);
                bleReceive = "";
            }
            bleMsg = "";
            if (this.widgetUpdate == loop || this.widgetUpdate == (0)) {
                switch (this.widgetType) {
                    case WidgetType.Databox:
                        bleMsg = String.fromCharCode(UISTART) + "C"/*DATA_OUT*/ + String.fromCharCode(this.widgetId) +
                            String.fromCharCode(this.widgetCoordX) + String.fromCharCode(this.widgetCoordY) +
                            String.fromCharCode(this.widgetWidth) + String.fromCharCode(this.widgetHeight) +
                            String.fromCharCode(this.widgetInputMode) +
                            String.fromCharCode(SEP) + String.fromCharCode(this.widgetColour) +
                            String.fromCharCode(SEP) + this.widgetTitle +
                            String.fromCharCode(SEP) + this.widgetUnit +
                            String.fromCharCode(SEP) + this.widgetData + String.fromCharCode(UIEND);
                        break;
                    case WidgetType.Databox_Circle:
                        bleMsg = String.fromCharCode(UISTART) + "G"/*DATA_OUT_CIRCLE*/ + String.fromCharCode(this.widgetId) +
                            String.fromCharCode(this.widgetCoordX) + String.fromCharCode(this.widgetCoordY) +
                            String.fromCharCode(this.widgetWidth) + String.fromCharCode(this.widgetHeight) +
                            String.fromCharCode(this.widgetInputMode) + //inputType
                            String.fromCharCode(SEP) + String.fromCharCode(this.widgetColour) +
                            String.fromCharCode(SEP) + this.widgetTitle +
                            String.fromCharCode(SEP) + this.widgetUnit +
                            String.fromCharCode(SEP) + this.widgetData + String.fromCharCode(UIEND);
                        break;
                    case WidgetType.Databox_Header:
                        bleMsg = String.fromCharCode(UISTART) + "H"/*DATA_OUT_HEADER*/ + String.fromCharCode(this.widgetId) +
                            String.fromCharCode(this.widgetCoordX) + String.fromCharCode(this.widgetCoordY) +
                            String.fromCharCode(this.widgetWidth) + String.fromCharCode(this.widgetHeight) +
                            String.fromCharCode(this.widgetInputMode) + //inputType
                            String.fromCharCode(SEP) + String.fromCharCode(this.widgetColour) +
                            String.fromCharCode(SEP) + this.widgetTitle + String.fromCharCode(UIEND);
                        break;

                    case WidgetType.Button:
                        bleMsg = String.fromCharCode(UISTART) + "B"/*BUTTON_IN*/ + String.fromCharCode(this.widgetId) +
                            String.fromCharCode(this.widgetCoordX) + String.fromCharCode(this.widgetCoordY) +
                            String.fromCharCode(this.widgetWidth) + String.fromCharCode(this.widgetHeight) +
                            "1" + //inputType button no ack
                            String.fromCharCode(SEP) + String.fromCharCode(this.widgetColour) +
                            String.fromCharCode(SEP) + this.widgetTitle + String.fromCharCode(UIEND);
                        break;
                    case WidgetType.Button_Circle:
                        bleMsg = String.fromCharCode(UISTART) + "J"/*CIRCLE_BUTTON*/ + String.fromCharCode(this.widgetId) +
                            String.fromCharCode(this.widgetCoordX) + String.fromCharCode(this.widgetCoordY) +
                            String.fromCharCode(this.widgetWidth) + String.fromCharCode(this.widgetHeight) +
                            "1" + //inputType button no ack
                            String.fromCharCode(SEP) + String.fromCharCode(this.widgetColour) +
                            String.fromCharCode(SEP) + this.widgetTitle + String.fromCharCode(UIEND);
                        break;
                    case WidgetType.Keyboard_In:
                        bleMsg = String.fromCharCode(UISTART) + "K"/*KEYBOARD_IN*/ + String.fromCharCode(this.widgetId) +
                            String.fromCharCode(this.widgetCoordX) + String.fromCharCode(this.widgetCoordY) +
                            String.fromCharCode(this.widgetWidth) + String.fromCharCode(this.widgetHeight) +
                            String.fromCharCode(this.widgetInputMode) + //inputType
                            String.fromCharCode(SEP) + String.fromCharCode(this.widgetColour) +
                            String.fromCharCode(SEP) + this.widgetTitle +
                            String.fromCharCode(SEP) + this.widgetData + String.fromCharCode(UIEND);
                        break;
                    case WidgetTypeInput.Slider:
                        bleMsg = String.fromCharCode(UISTART) + "Q"/*SLIDER_IN*/ + String.fromCharCode(this.widgetId) +
                            String.fromCharCode(this.widgetCoordX) + String.fromCharCode(this.widgetCoordY) +
                            String.fromCharCode(this.widgetWidth) + String.fromCharCode(this.widgetHeight) +
                            String.fromCharCode(this.widgetInputMode) + //inputType
                            String.fromCharCode(SEP) + String.fromCharCode(this.widgetColour) +
                            String.fromCharCode(SEP) + this.widgetTitle +
                            String.fromCharCode(SEP) + this.widgetData +
                            String.fromCharCode(SEP) + convertNumberToString(this.widgetMaxValue) +
                            String.fromCharCode(SEP) + convertNumberToString(this.widgetMinValue) +
                            String.fromCharCode(SEP) + String.fromCharCode(this.widgetSliderSteps) +
                            String.fromCharCode(SEP) + String.fromCharCode(this.widgetSliderForceUpdate) + String.fromCharCode(UIEND);
                        this.widgetSliderForceUpdate = 48;
                        break;
                    case WidgetTypeInput.Analog_Dial:
                        bleMsg = String.fromCharCode(UISTART) + "R"/*ANALOG_DIAL_OUT*/ + String.fromCharCode(this.widgetId) +
                            String.fromCharCode(this.widgetCoordX) + String.fromCharCode(this.widgetCoordY) +
                            String.fromCharCode(this.widgetWidth) + String.fromCharCode(this.widgetHeight) +
                            String.fromCharCode(this.widgetInputMode) + //inputType
                            String.fromCharCode(SEP) + String.fromCharCode(this.widgetColour) +
                            String.fromCharCode(SEP) + this.widgetTitle +
                            String.fromCharCode(SEP) + this.widgetUnit +
                            String.fromCharCode(SEP) + this.widgetData +
                            String.fromCharCode(SEP) + convertNumberToString(this.widgetMaxValue) +
                            String.fromCharCode(SEP) + convertNumberToString(this.widgetMinValue) + String.fromCharCode(UIEND);
                        break;
                    case WidgetTypeInput.Joystick:
                        bleMsg = String.fromCharCode(UISTART) + "U"/*JOYSTICK*/ + String.fromCharCode(this.widgetId) +
                            String.fromCharCode(this.widgetCoordX) + String.fromCharCode(this.widgetCoordY) +
                            String.fromCharCode(this.widgetWidth) + String.fromCharCode(this.widgetHeight) +
                            String.fromCharCode(this.widgetInputMode) + //inputType
                            String.fromCharCode(SEP) + String.fromCharCode(this.widgetColour) +
                            String.fromCharCode(SEP) + this.widgetTitle +
                            String.fromCharCode(SEP) + this.widgetUnit +
                            String.fromCharCode(SEP) + this.widgetData + String.fromCharCode(UIEND);
                        break;

                    default:
                        //serial.writeString("update error");
                        break;
                }
                /////////////////////////////////Sending data to BLE////////////////////////////////////            
                packetBreak = Math.idiv(bleMsg.length, 20) + 1;
                for (let i = 0; i < packetBreak; i++) {
                    //tempString = bleMsg.substr((i * 20), 20);
                    //bluetooth.uartWriteString(tempString);
                    //serial.writeLine(tempString);
                    if(i == (packetBreak - 1))
                    {
                        bluetooth.uartWriteString(bleMsg.substr((i * 20), (bleMsg.length % 20)));
                    }
                    else{
                        bluetooth.uartWriteString(bleMsg.substr((i * 20), 20));
                    }
                }                
                this.widgetUpdate = 1;
            }
            else {
                this.widgetUpdate += 1;
            }
        }


    }
    /**
     * Block to begin Andee Services
     */
    //% weight=100
    //% blockId=Andee_begin
    //% block="Andee Begin"
    export function begin(): void {
        reply_flag = false;
        ble_reply = "";
        bluetooth.startUartService();
        bluetooth.onUartDataReceived("]", () => {
            bleReceive = bluetooth.uartReadUntil("]");
            reply_flag = true;
        });
    }
    /**
     * Raises an Andee event in the event bus using PXT Control functions
     * @param id ID of the Widget, eg: WidgetId.Widget_1
     */
    //% weight=70 blockGap=8 blockId="Andee_event" block="Widget Event|%id"
    //% blockExternalInputs=1
    export function WidgetEvent(id: WidgetId, action: Action): void {
        control.onEvent(id + 30 /*EVENT_ID_OFFSET*/, 62 /*ANDEE_EVENT_VALUE*/, action);
    }

    /**
     * Create Widget
     * @param id ID of Widget, eg: WidgetId.Widget_1
     * @param widgetType Type of Widget, eg: WidgetType.Databox
     * @param position Position of Widget, eg: WidgetPosition.Row0_Column0
     * @param length Length of Widget, eg: WidgetLength.Half
     * @param colour Colour of Widget, eg: WidgetColour.Red
     * @param title Title of Widget, eg: "Title"
     * @param data Widget Data Display, eg: "Data"
     * @param unit Widget Units Display, eg: "Units"
     */
    //% weight=95
    //% blockId=create_widget icon="\u0041
    //% block="Create Widget: %id|Widget Type%widgetType|Position%position|Widget Length%WidgetLength|Widget Colour%WidgetColour|Widget Title%title|Widget Data%data|Widget Units%unit"
    //% widgetType.fieldEditor="gridpicker" widgetType.fieldOptions.columns=3
    //% position.fieldEditor="gridpicker" position.fieldOptions.columns=4
    //% WidgetColour.fieldEditor="gridpicker" WidgetColour.fieldOptions.columns=2
    export function createWidget(id: WidgetId, widgetType: WidgetType, position: WidgetPosition, length: WidgetLength,
        colour: WidgetColour, title: string, data: string, unit: string): Widget {
        let widget = new Widget();
        let imd: number;

        widget.setId(id);
        widget.setType(widgetType);
        widget.setColour(colour);

        widget.setHeight(20);
        imd = Math.idiv(position, 4);
        widget.setCoordY((imd * 20) + ((imd + 1) * 4));//calculating y coordinate
        imd = position - (Math.idiv(position, 4) * 4);
        widget.setCoordX((imd * 20) + ((imd + 1) * 4));//calculating x coordinate

        switch (length) {
            case WidgetLength.One_Quarter: //one_quarter
                widget.setWidth(20);
                break;
            case WidgetLength.Half: //half
                widget.setWidth(44);
                break;
            case WidgetLength.Full: //full
                widget.setWidth(92);
                break;
            default:
                //serial.writeString("length error");
                break;
        }


        widget.setTitle(title);
        widget.setData(data);
        widget.setUnit(unit);
        widget.forceUpdate();
        return widget;
    }
    /**
     * Create Slider/Analog Circle Widget
     * @param id ID of Widget, eg: WidgetId.Widget_1
     * @param widgetType Type of Widget, eg: WidgetTypeInput.Slider
     * @param position Position of Widget,eg: WidgetPosition.Row0_Column0
     * @param length Length of Widget, eg: WidgetLength.Full
     * @param colour Colour of Widget, eg: WidgetColour.Red
     * @param title Title of Widget, eg: "Title"     
     * @param unit Widget Units Display,eg: "Units"
     * @param currentValue Widget Current Value for Display, eg: "0"
     * @param maxValue Max Value for Display, eg: 100
     * @param minValue Min Value for Display, eg: 0
     * @param sliderSteps Number of steps for slider, eg: 100
     */
    //% weight=90
    //% blockId=create_slider_widget icon="\u0041
    //% block="Create Slider/|AnalogCircle Widget: %id|Widget Type%widgetType|Position%position|Widget Length%WidgetLength|Widget Colour%WidgetColour|Widget Title%title|Widget Units%unit|Current Value%currentValue|Max Value%maxValue|Min Value%minValue|No. of Steps%sliderSteps"
    //% position.fieldEditor="gridpicker" position.fieldOptions.columns=4
    //% WidgetColour.fieldEditor="gridpicker" WidgetColour.fieldOptions.columns=2
    export function createSliderWidget(id: WidgetId, widgetType: WidgetTypeInput, position: WidgetPosition, length: WidgetLength,
        colour: WidgetColour, title: string, unit: string, currentValue: string, maxValue: number, minValue: number, sliderSteps: number): Widget {
        let widget = new Widget();
        let imd: number;

        widget.setId(id);
        widget.setType(widgetType);
        widget.setColour(colour);

        widget.setHeight(20);
        imd = Math.idiv(position, 4);
        widget.setCoordY((imd * 20) + ((imd + 1) * 4));//calculating y coordinate
        imd = position - (Math.idiv(position, 4) * 4);
        widget.setCoordX((imd * 20) + ((imd + 1) * 4));//calculating x coordinate

        switch (length) {
            case WidgetLength.One_Quarter: //one_quarter
                widget.setWidth(20);
                break;
            case WidgetLength.Half: //half
                widget.setWidth(44);
                break;
            case WidgetLength.Full: //full
                widget.setWidth(92);
                break;
            default:
                //serial.writeString("length error");
                break;
        }
        widget.setTitle(title);
        widget.setData(currentValue);
        widget.setUnit(unit);
        widget.setMinMax(minValue, maxValue);
        widget.setSliderSteps(sliderSteps);
        widget.forceUpdate();
        return widget;
    }
    /**
     * Create Joystick Widget
     * @param id ID of Widget, eg: WidgetId.Widget_1
     * @param position Position of Widget,eg: WidgetPosition.Row0_Column0
     * @param length Length of Widget, eg: WidgetLength.Full
     * @param colour Colour of Widget, eg: WidgetColour.Red
     * @param title Title of Widget, eg: "Title"     
     * @param xMax X Axis Max Value,eg: "100"
     * @param yMax Y Axis Max Value, eg: "100"
     */
    //% weight=100
    //% blockId=create_joystick_widget icon="\u0041
    //% block="Create Joystick Widget: %id|Position%position|Widget Length%WidgetLength|Widget Colour%WidgetColour|Widget Title%title|X Axis Max Value%xMax|Y Axis Max Value%yMax|"
    //% position.fieldEditor="gridpicker" position.fieldOptions.columns=4
    //% WidgetColour.fieldEditor="gridpicker" WidgetColour.fieldOptions.columns=2
    //% advanced=true
    export function createJoystickWidget(id: WidgetId, position: WidgetPosition, length: WidgetLength,
        colour: WidgetColour, title: string, xMax: string, yMax: string): Widget {
        let widget = new Widget();
        let imd: number;

        widget.setId(id);
        widget.setType(WidgetTypeInput.Joystick);
        widget.setColour(colour);

        widget.setHeight(20);
        imd = Math.idiv(position, 4);
        widget.setCoordY((imd * 20) + ((imd + 1) * 4));//calculating y coordinate
        imd = position - (Math.idiv(position, 4) * 4);
        widget.setCoordX((imd * 20) + ((imd + 1) * 4));//calculating x coordinate

        switch (length) {
            case WidgetLength.One_Quarter: //one_quarter
                widget.setWidth(20);
                break;
            case WidgetLength.Half: //half
                widget.setWidth(44);
                break;
            case WidgetLength.Full: //full
                widget.setWidth(92);
                break;
            default:
                //serial.writeString("length error");
                break;
        }
        widget.setTitle(title);
        widget.setData(yMax);
        widget.setUnit(xMax);
        widget.forceUpdate();
        return widget;
    }
    /**
     * Block to clear all Widgets
     */
    //% weight=13
    //% blockId=Andee_clear
    //% block="Clear All Widgets"
    //% advanced=true
    export function clear(): void {
        bleMsg = ""
        bleMsg = String.fromCharCode(COMMANDSTART) + "L"/*CLEAR*/ + String.fromCharCode(COMMANDEND);
        bluetooth.uartWriteString(bleMsg);
        bleMsg = "";
    }

    /**
     * Block to return keyboard widget string
     */
    //% weight=65
    //% blockId=get_keyboard_reply
    //% block="Get Keyboard Reply"
    export function getKeyboard(): string {
        return ble_reply;
    }
    /**
     * Block to return value of slider widget as a number
     */
    //% weight=50
    //% blockId=get_slider_value
    //% block="Get Slider Value"
    export function getSlider(): number {
        return parseInt(ble_reply);
    }
    /**
     * Block to return a boolean if button is pressed once or more than once
     * Returns true if button is pressed more than once
     * Returns false if button is pressed once
     */
    //% weight=73
    //% blockId=get_button_press
    //% block="Button is pressed more than once"
    //% advanced=true
    export function getButtonPress(): boolean {
        let buttonPress = ble_reply.charCodeAt(0) - 32
        if (buttonPress > 1) {
            return true
        }
        else {
            return false
        }
    }
    /**
     * Block to store values of joystick widget as a number
     */
    //% weight=99
    //% blockId=get_joystick_value
    //% block="Get Joystick Value"
    //% advanced=true
    export function getJoystick(): number[] {
        let num = parseInt(ble_reply.substr(0, 4));
        let num2 = parseInt(ble_reply.substr(4, 4));
        let array: number[] = [num, num2];
        return array
    }

    /**
     * Function to convert numbers to string
     * @param num Number to be converted to string
     */
    //% weight=15
    //% blockId=convert_number
    //% block="Convert %num| to String"
    //% advanced=true
    export function convertNumberToString(num: number): string {
        return (num.toString());
    }

    export function printToDEC(buffer: string): void {
        let replyDecimal: string;
        let decimal: number;
        for (let i = 0; i < buffer.length; i++) {
            decimal = buffer.charCodeAt(i);
            replyDecimal = replyDecimal + " " + decimal + " ";
        }
        //serial.writeLine(replyDecimal);
    }

    export function trimString(str: string): string {
        if (str.length > 14) {
            str + "..";
            return str.substr(0, 12)+"..";
        }
        else {
            return str;
        }
    }

}

