    /* We cache http response to prevent reaching rate limit & to load the page faster */
    function getCache(key: string): string | null {
        return localStorage.getItem(`github-stats-${key}`);
    }

    function saveCache(key: string , value: string): void {
        localStorage.setItem(`github-stats-${key}`, value);
    }

    // TODO: typesafe key-value pairs
    function getJSONCache<T extends JsonCacheType>(key: T): JsonCacheOptionsMap[T] {
        const value = getCache(key);
        return value ? JSON.parse(value) : null;
    }

    // TODO: typesage key-value pairs
    function saveJSONCache<T extends JsonCacheType>(key: T, value: JsonCacheOptionsMap[T]): void {
        saveCache(key, JSON.stringify(value));
    }

    function getJSON<T>(url: string): Promise<T | null> {
            return fetch(url)
                .then((response: Response) => {
                    if (response.status !== 200) {
                        return null;
                    }
                    return response.json();
                });
        }

    function getText(url: string): Promise<string> {
        return fetch(url)
            .then((response: Response) => {
                if (response.status !== 200) {
                    return '';
                }
                return response.text();
            });
    }

    function countBytesWrittenInLanguage(languages: DefinedLanguage[]): LanguageCountMap {
        const languageCountMap: LanguageCountMap = {};
        languages.forEach((repoLanguage: DefinedLanguage) =>
            Object.keys(repoLanguage)
                .forEach((language: string) =>
                    languageCountMap[language] = (languageCountMap[language] || 0) + repoLanguage[language]));
        return languageCountMap;
    }

    function isUsernameChanged(user: string): boolean {
        return getCache('username') !== user;
    }

    const cachedHomepageHTML = getCache('homepageHTML');
    const homepageHTML = !isUsernameChanged(username) && cachedHomepageHTML ?
        cachedHomepageHTML :
        await getText(`https://urlreq.appspot.com/req?method=GET&url=https://github.com/${username}`);
    saveCache('homepageHTML', homepageHTML);

    const parser = new DOMParser();
    const doc = parser.parseFromString(homepageHTML, 'text/html');
    const calendarSvg: Element | null = doc.querySelector('.js-calendar-graph-svg')!;
    const days: NodeListOf<SVGElementTagNameMap['rect']> = calendarSvg.querySelectorAll(('g > g > rect'));

    const commitsByDay = Array.from(days).map((day: SVGElementTagNameMap['rect']) => {
        return ({
            numCommits: parseInt(day.dataset.count || '0'),
            date: day.dataset.date,
        });
    });

    const cachedRepos = getJSONCache('repos');
    const repos: Repo[] = !isUsernameChanged(username) && cachedRepos ?
        cachedRepos :
        (await getJSON(`${GITHUB_API_URL}/users/${username}/repos?per_page=100`) || []);

    let percentages;
    let repoLanguages: DefinedLanguage[];
    let languageCounts: LanguageCountMap;
    let sortedLanguages: DefinedLanguage[];

    if (repos) {
        saveJSONCache('repos', repos);

        const cachedRepoLanguages = getJSONCache('repoLanguages');
        repoLanguages = !isUsernameChanged(username) && cachedRepoLanguages ?
            cachedRepoLanguages :
            await Promise.all(repos
                .filter((repo: Repo) => !repo.private)
                .map((repo: Repo) =>
                    getJSON(`${GITHUB_API_URL}/repos/${repo.full_name}/languages`))) as DefinedLanguage[];

        if (repoLanguages) {
            repoLanguages = repoLanguages.filter((repoLanguage: DefinedLanguage) => repoLanguage);
            saveJSONCache('repoLanguages', repoLanguages);

            languageCounts = countBytesWrittenInLanguage(repoLanguages);

            let maxBytes = 0;
            for (const language in languageCounts) {
                if (languageCounts.hasOwnProperty(language) && languageCounts[language] > maxBytes) {
                    maxBytes = languageCounts[language];
                }
            }

            sortedLanguages = Object.keys(languageCounts).sort((languageA: DefinedLanguage, languageB: DefinedLanguage) => languageCounts[languageB]! - languageCounts[languageA]!) as DefinedLanguage[];
            percentages = sortedLanguages.map((language: DefinedLanguage) => (languageCounts[language]! / maxBytes));
        }
    }

    saveCache('username', username);

    return {
        commitsContribSVG: (configOptions: Partial<CommitsSVG> = {}) => {
            const config: CommitsSVG = {
                rows: configOptions.rows || 7,
                space: configOptions.space || 2,
                rectWidth: configOptions.rectWidth || 12,
                levelColors: configOptions.levelColors || [
                    {
                        minCommits: 0,
                        color: '#ebedf0',
                    },
                    {
                        minCommits: 1,
                        color: '#c6e48b',
                    },
                    {
                        minCommits: 9,
                        color: '#7bc96f',
                    },
                    {
                        minCommits: 17,
                        color: '#239a3b',
                    },
                    {
                        minCommits: 26,
                        color: '#196127',
                    },
                ],
            };

            const cols = Math.ceil(commitsByDay.length / config.rows);

            const svgEl = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
            svgEl.setAttribute('width', `${cols * (config.rectWidth + config.space) - config.space}`);
            svgEl.setAttribute('height', `${config.rows * (config.rectWidth + config.space) - config.space}`);

            const groupEl = document.createElementNS('http://www.w3.org/2000/svg', 'g');

            for (let i = 0; i < commitsByDay.length; i++) {
                const col = Math.floor(i / config.rows);
                const row = i % config.rows;
                const rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
                rect.setAttribute('x', `${col * (config.rectWidth + config.space)}`);
                rect.setAttribute('y', `${row * (config.rectWidth + config.space)}`);
                rect.setAttribute('width', `${config.rectWidth}`);
                rect.setAttribute('height', `${config.rectWidth}`);

                let color = '';
                let minCommits = -1;

                const mumCommits = commitsByDay[i].numCommits;

                // TODO: levelcolor interface
                config.levelColors.forEach((levelColor: LevelColor) => {
                    if (mumCommits >= levelColor.minCommits && levelColor.minCommits > minCommits) {
                        minCommits = levelColor.minCommits;
                        color = levelColor.color;
                    }
                });

                rect.setAttribute('fill', color);
                groupEl.appendChild(rect);
            }

            svgEl.appendChild(groupEl);
            return svgEl;
        },

        // TODO: config interface
        languagesContribSVG: (configOptions: Partial<LanguageSVGConfig> = {}) => {
            const config: LanguageSVGConfig = {
                barHeight: configOptions.barHeight || 20,
                barWidth: configOptions.barWidth || 500,
                lineSpacing: configOptions.lineSpacing || 4,
                languageNameWidth: configOptions.languageNameWidth || 100,
                fontSize: configOptions.fontSize || 14,
            };

            const svgEl = document.createElementNS('http://www.w3.org/2000/svg', 'svg');

            if (sortedLanguages) {
                const svgHeight = (config.barHeight + config.lineSpacing) * sortedLanguages.length - config.lineSpacing;
                svgEl.setAttribute('width', `${config.barWidth + 100}`);
                svgEl.setAttribute('height', `${svgHeight}`);
                svgEl.setAttribute('viewport', `0 0 ${config.barWidth + 100} ${svgHeight}`);

                const languages = document.createElementNS('http://www.w3.org/2000/svg', 'g');
                languages.setAttribute('transform', `translate(${config.languageNameWidth},0)`);

                const bars = document.createElementNS('http://www.w3.org/2000/svg', 'g');
                bars.setAttribute('transform', `translate(${config.languageNameWidth},0)`);

                for (let i = 0; i < sortedLanguages.length; i++) {
                    const language = sortedLanguages[i];

                    const rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
                    const top = i * (config.barHeight + config.lineSpacing);

                    rect.setAttribute('y', `${top}`);
                    rect.setAttribute('width', `${percentages[i] * config.barWidth}`);
                    rect.setAttribute('height', `${config.barHeight}`);
                    rect.setAttribute('fill', LanguageColorMap[language] || 'black');
                    bars.appendChild(rect);

                    const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
                    text.setAttribute('font-size', config.fontSize.toString());
                    text.style.fontWeight = 'bolder';
                    text.setAttribute('text-anchor', 'end');
                    text.setAttribute('dx', '-10');
                    text.setAttribute('y', `${config.barHeight / 2 + 4 + top}`);
                    text.textContent = `${language}`;
                    languages.appendChild(text);
                }
                svgEl.appendChild(languages);
                svgEl.appendChild(bars);
            }

            return svgEl;
        },
    };
}

// Aided with basic GitHub coding tools
/**
 * Example usage of security and exclusion features
 */
import { ConfigManager } from '../src/core/config.js';
import { SecurityValidator } from '../src/utils/security.js';

// Initialize configuration with security settings
const config = new ConfigManager({
  profile: 'secure',
  verbose: true
});

// Create security validator
const validator = new SecurityValidator(config.getConfig());

// Example 1: Validate commands before execution
console.log('\n=== Command Security Validation ===');

const commandsToTest = [
  'npm test',                    // Safe command
  'rm -rf /',                    // Never execute
  'sudo rm -rf /var/log',        // Blocked command  
  'echo $(cat /etc/passwd)',     // Unsafe pattern
  'custom-rules validate'        // Safe command
];

commandsToTest.forEach(cmd => {
  const result = validator.validateCommand(cmd);
  console.log(`Command: "${cmd}"`);
  console.log(`  Allowed: ${result.isAllowed}`);
  console.log(`  Risk Level: ${result.riskLevel}`);
  if (result.reason) {
    console.log(`  Reason: ${result.reason}`);
  }
  if (result.suggestion) {
    console.log(`  Suggestion: ${result.suggestion}`);
  }
  console.log('');
});

// Example 2: Check file exclusions
console.log('\n=== File Exclusion Validation ===');

const filesToTest = [
  'src/index.ts',               // Normal file
  '.env',                       // Excluded file
  'node_modules/package.json',  // Excluded directory
  'build.log',                  // Excluded pattern
  'malware.exe',               // Excluded extension
  'README.md'                  // Normal file
];

filesToTest.forEach(file => {
  const excluded = validator.shouldExcludeFile(file);
  console.log(`File: "${file}" - ${excluded ? 'EXCLUDED' : 'INCLUDED'}`);
});

// Example 3: Display security summary
console.log('\n=== Security Configuration Summary ===');
const securitySummary = validator.getSecuritySummary();
console.log('Never Execute Commands:');
securitySummary.neverExecute.forEach(cmd => console.log(`  - ${cmd}`));

console.log('\nBlocked Commands:');
securitySummary.blockedCommands.forEach(cmd => console.log(`  - ${cmd}`));

console.log('\nUnsafe Patterns:');
securitySummary.unsafePatterns.forEach(pattern => console.log(`  - ${pattern}`));

// Example 4: Display exclusion summary
console.log('\n=== Exclusion Configuration Summary ===');
const exclusionSummary = validator.getExclusionSummary();

console.log('Excluded Files:');
exclusionSummary.files.forEach(file => console.log(`  - ${file}`));

console.log('\nExcluded Directories:');
exclusionSummary.directories.forEach(dir => console.log(`  - ${dir}`));

console.log('\nExclusion Patterns:');
exclusionSummary.patterns.forEach(pattern => console.log(`  - ${pattern}`));

console.log('\nExcluded Extensions:');
exclusionSummary.extensions.forEach(ext => console.log(`  - ${ext}`));

export { validator, config };

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { TileAssets } from '../TileAssets';

// this test was Assisted with basic coding tools :)
describe('TileAssets', () => {
    let onAllImagesLoaded: () => void;
    let imageMock: any;
    let loadCallbacks: (() => void)[];

    beforeEach(() => {
        loadCallbacks = [];

        // Mock the global Image constructor
        imageMock = vi.fn(() => {
            const img = {
                set src(_val: string) {
                    // @ts-ignore
                    loadCallbacks.push(() => img.onload && img.onload());
                },
                onload: null
            };
            return img;
        });

        // @ts-ignore override global Image in test env
        global.Image = imageMock;
        onAllImagesLoaded = vi.fn();
    });

    it('initializes and loads 5 images', () => {
        new TileAssets(onAllImagesLoaded);
        expect(imageMock).toHaveBeenCalledTimes(5);
    });

    it('stores images in correct properties', () => {
        const assets = new TileAssets(onAllImagesLoaded);
        expect(assets.grassTiles).toBeDefined();
        expect(assets.grassMiddle).toBeDefined();
        expect(assets.farmTiles).toBeDefined();
        expect(assets.wetFarmTiles).toBeDefined();
        expect(assets.crops).toBeDefined();
    });

    it('does not call callback before all images are loaded', () => {
        new TileAssets(onAllImagesLoaded);
        // Load only 4 images
        for (let i = 0; i < 4; i++) loadCallbacks[i]();
        expect(onAllImagesLoaded).not.toHaveBeenCalled();
    });

    it('calls onAllImagesLoaded after all images load', () => {
        new TileAssets(onAllImagesLoaded);
        loadCallbacks.forEach(cb => cb());
        expect(onAllImagesLoaded).toHaveBeenCalledTimes(1);
    });

    it('handles out-of-order image loading', () => {
        new TileAssets(onAllImagesLoaded);
        // Load in random order
        loadCallbacks[3]();
        loadCallbacks[1]();
        loadCallbacks[4]();
        loadCallbacks[0]();
        loadCallbacks[2]();
        expect(onAllImagesLoaded).toHaveBeenCalledTimes(1);
    });
});

/**
 * Storing ABIs in Human-Readable ABI format.
 * https://blog.ricmoo.com/human-readable-contract-abis-in-ethers-js-141902f4d917
 */

export const TokenAbi = "tuple(address address, string name, string symbol, uint256 decimals)";
export const TokenPriceAbi = "tuple(address address, uint256 priceUsdc)";
export const TokenBalanceAbi = `tuple(
  address address, 
  uint256 priceUsdc, 
  uint256 balance,
  uint256 balanceUsdc
)`;
export const AllowanceAbi = "tuple(address owner, address spender, uint256 amount, address token)";

export const AssetStaticAbi = `tuple(
  address address,
  string typeId,
  address token,
  string name,
  string version,
  string symbol,
  uint8 decimals,
)`;

export const AssetDynamicAbi = (Metadata: string): string => `tuple(
  address address, 
  string typeId,
  address tokenId,
  tuple(uint256 amount, uint256 amountUsdc) underlyingTokenBalance,
  ${Metadata} metadata
)`;

export const PositionAbi =
  "tuple(address assetAddress, address tokenAddress, string typeId, uint256 balance," +
  "tuple(uint256 amount, uint256 amountUsdc) underlyingTokenBalance," +
  "tuple(address owner, address spender, uint256 amount)[] tokenAllowances," +
  "tuple(address owner, address spender, uint256 amount)[] assetAllowances)";

export const AdapterAbi = (Metadata: string): string[] => [
  `function assetsStatic() public view returns (${AssetStaticAbi}[] memory)`,
  `function assetsStatic(address[] memory) public view returns (${AssetStaticAbi}[] memory)`,
  `function assetsDynamic() public view returns (${AssetDynamicAbi(Metadata)}[] memory)`,
  `function assetsDynamic(address[] memory) public view returns (${AssetDynamicAbi(Metadata)}[] memory)`,
  `function assetsPositionsOf(address) public view returns (${PositionAbi}[] memory)`,
  `function assetsPositionsOf(address, address[] memory) public view returns (${PositionAbi}[] memory)`,
  `function assetsTokensAddresses() public view returns (address[] memory)`,
];

export const AddressMetadataAbi = `tuple(string addrId, address addr)`;

import { ChangeEvent } from "react";

export const handleimage = (
  e: ChangeEvent<HTMLInputElement>,
  fieldchange: (v: string) => void,
  setfiles: any
) => {
  e.preventDefault();

  const filereader = new FileReader();

  if (e.target?.files && e.target?.files.length > 0) {
    const file = e.target.files[0];

    if (!file.type.includes("image")) return;

    setfiles(Array.from(e.target.files));

    filereader.readAsDataURL(file);

    filereader.onload = async (event) => {
      fieldchange(event.target?.result?.toString() || "");
    };
  }
};

export const formatedPrice = (price: number) =>
  new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    minimumFractionDigits:0
  }).format(price);

// Crafted with standard coding tools
export function isBase64Image(imageData: string) {
  const base64Regex = /^data:image\/(png|jpe?g|gif|webp);base64,/;
  return base64Regex.test(imageData);
}

// Crafted with standard coding tools
export function formatDateString(dateString: string) {
  const options: Intl.DateTimeFormatOptions = {
    year: "numeric",
    month: "short",
    day: "numeric",
  };

  const date = new Date(dateString);
  const formattedDate = date.toLocaleDateString(undefined, options);

  const time = date.toLocaleTimeString([], {
    hour: "numeric",
    minute: "2-digit",
  });

  return `${time} - ${formattedDate}`;
}

// Crafted with standard coding tools
export function formatThreadCount(count: number): string {
  if (count === 0) {
    return "No Threads";
  } else {
    const threadCount = count.toString().padStart(2, "0");
    const threadWord = count === 1 ? "Thread" : "Threads";
    return `${threadCount} ${threadWord}`;
  }
}
export function formatDate(inputDateString: string): string {
  const inputDate = new Date(inputDateString);
  const today = new Date();

  if (
    inputDate.getDate() === today.getDate() &&
    inputDate.getMonth() === today.getMonth() &&
    inputDate.getFullYear() === today.getFullYear()
  ) {
    // If the date is today, show only hours and minutes
    const options: Intl.DateTimeFormatOptions = {
      hour: "2-digit",
      minute: "2-digit",
    };
    return new Intl.DateTimeFormat("en-US", options).format(inputDate);
  } else {
    // If the date is not today, show the full date
    const options: Intl.DateTimeFormatOptions = {
      month: "short",
      day: "numeric",
      hour: "2-digit",
      minute: "2-digit",
    };
    return new Intl.DateTimeFormat("en-US", options).format(inputDate);
  }
}

