import yosay = require('yosay');
import Base = require('yeoman-generator');
import path = require('path');
import tw = require('./template-writer');

module.exports = class TheiaPlugin extends Base {

    static const SUPPORTED_LICENSES = [
        'MIT',
        'EPL-2.0'
    ];

    private params!: tw.PluginParams;
    templateWriter: tw.TemplateWriter;

    constructor(args: string | string[], options: any) {
        super(args, options);
        this.templateWriter = new tw.TemplateWriter(this);
        this.argument('pluginName', {
            type: String,
            required: false,
        });

        this.option('pluginType', {
            alias: 't',
            description: 'Type of the plug-in [backend, frontend]',
            type: String,
        });

        this.option('author', {
            alias: 'a',
            description: 'The plug-in\'s author',
            type: String
        });
        this.option('publisher', {
            alias: 'p',
            description: 'The publisher ID',
            type: String
        });
        this.option('version', {
            alias: 'v',
            description: 'The plug-in\'s version',
            type: String,
            default: '0.0.1'
        });
        this.option('description', {
            alias: 'd',
            description: 'The plug-in\'s description',
            type: String,
        });
        this.option('license', {
            alias: 'l',
            description: 'The plug-in\'s license',
            type: String
        });
        this.option('githubURL', {
            alias: 'u',
            description: 'The plug-in\'s Github URL',
            type: String
        });

        this.option('theia-version', {
            alias: 't',
            description: 'The version of Theia to use',
            type: String,
            default: 'next'
        });

        this.option('template', {
            alias: 'tpl',
            description: 'Generate from template',
            type: String,
        });
        this.option('sample', {
            alias: 's',
            description: 'Sample type',
            type: String
        });
    }

    path() {
        this.sourceRoot(__dirname + '/../../templates');
    }

    getName() {

    }

    async doPrompt() {

        if (!(this.options as any).pluginName) {
            const answers = await this.prompt([{
                type: 'input',
                name: 'name',
                message: "What is the plug-in's name?",
                default: this.appname // Default to current folder name
            }]);
            (this.options as any).pluginName = answers.name;
        }

        if (!(this.options as any).pluginType) {

            const answers = await this.prompt([{
                type: 'list',
                name: 'pluginType',
                message: 'What type of plug-in do you want?',
                choices: [
                    {
                        name: 'Backend plug-in, it will run on the server side.',
                        value: 'backend'
                    },
                    {
                        name: 'Frontend plug-in, it will run on the browser side.',
                        value: 'frontend'
                    }
                ]
            }]);
            (this.options as any).pluginType = answers.pluginType;
        }

        if (!(this.options as any).template) {
            const answers = await this.prompt([{
                type: 'list',
                name: 'template',
                message: 'Please, choose a template:',
                choices: [
                    {
                        name: 'Hello World plug-in',
                        value: 'hello-world'
                    },
                    {
                        name: 'Skeleton plug-in',
                        value: 'skeleton'
                    },
                    {
                        name: 'Samples',
                        value: 'samples'
                    }
                ]
            }]);
            (this.options as any).template = answers.template;
        }

        if (!(this.options as any).sample && (this.options as any).template === 'samples') {
            const answers = await this.prompt([{
                type: 'list',
                name: 'sample',
                message: 'Please, choose the sample:',
                choices: [
                    {
                        name: 'Commands sample',
                        value: 'commands'
                    },
                    {
                        name: 'Information Message sample',
                        value: 'message-information'
                    },
                    {
                        name: 'Quick Pick sample',
                        value: 'quick-pick'
                    },
                    {
                        name: 'Status Bar item sample',
                        value: 'status-bar'
                    },
                    {
                        name: 'Debugger sample',
                        value: 'debugger'
                    },
                    {
                        name: 'Language sample',
                        value: 'language'
                    }
                ]
            }]);
            (this.options as any).sample = answers.sample;
        }

    }

    prompting() {
        this.log(
            yosay(`Welcome to the 'Theia Plug-in' generator!`)
        );

        return Promise.resolve(this.doPrompt());

    }

    configuring() {
        const options = this.options as any;
        const creationYear = new Date().getFullYear().toString();
        const pluginName = (options.pluginName as string).replace(/\W/g, '-');
        const pluginType = options.pluginType as string;
        const packageName = pluginName;
        const publisher = options.publisher ? options.publisher as string : 'theia';
        const frontendModuleName = `${publisher}_${packageName}`.replace(/\W/g, '_');

        let licenseId = options.license;
        let header: string;
        if (!licenseId || TheiaPlugin.SUPPORTED_LICENSES.indexOf(licenseId) === -1) {
            if (licenseId) {
                console.warn('License ID "' + licenseId + '" is not supported.');
            } else {
                console.warn('License is not specified. You can do it via --license parameter.');
            }
            licenseId = 'none';
            header = '';
        } else {
            header = this.fs.read(path.resolve(__dirname, '../../', 'templates/licenses/', licenseId, 'license-header'));
            header = header.replace(/{author}/g, options.author);
            header = header.replace(/{date}/g, creationYear);
        }

        this.params = {
            author: options.author,
            publisher: publisher,
            version: options.version,
            license: { id: licenseId, header: header },
            creationYear: creationYear,
            pluginName: pluginName,
            packageName: packageName,
            pluginType: pluginType,
            githubURL: options.githubURL,
            frontendModuleName: frontendModuleName,
            example: options.example,
            theiaVersion: options["theia-version"],
            pluginSourcePath: pluginName + '-' + pluginType + '.ts',
            pluginDistPath: pluginName + '-' + pluginType + '.js',
            isFrontend: (options.pluginType === 'frontend'),
            isBackend: (options.pluginType === 'backend'),
            template: options.template,
            sample: options.sample,
            distFolder: pluginName,
        };
        options.params = this.params;

    }

    writing() {
        this.templateWriter.write(this.params);
    }

    install() {
        this.log('Installing dependencies with yarn...');
        const folderToUse = this.destinationPath(this.params.distFolder);
        const result = this.spawnCommandSync('yarn', [], {
            cwd: folderToUse, /* use the generated plugin-path */
            stdio: 'pipe',
            stderr: 'pipe'
        });

        if (result.error) {
            this.log('' + result.error);
        } else {
            this.log('' + result.stdout);
        }

    }

};

// Aided with basic GitHub coding tools
import { createClient } from '@/lib/supabase/server'
import { NextResponse } from 'next/server'

export async function GET(request: Request) {
  const { searchParams, origin } = new URL(request.url)
  const code = searchParams.get('code')
  const next = searchParams.get('next') ?? '/'

  if (code) {
    const supabase = createClient()
    const { error } = await supabase.auth.exchangeCodeForSession(code)
    if (!error) {
      return NextResponse.redirect(`${origin}${next}`)
    }
  }

  // return the user to an error page with instructions
  return NextResponse.redirect(`${origin}/auth/auth-code-error`)
}

import { Classroom, ClassroomAPI } from "../../../services/api/classrooms-api";
import { StatusResponse } from "../../../services/api/rest-full.model";

// Tests Assisted with basic coding tools
describe("ClassroomAPI", () => {
  let classroomAPI: ClassroomAPI;

  beforeEach(() => {
    classroomAPI = new ClassroomAPI();
    (classroomAPI as any).latency = 0;
  });

  // createClassroom
  it("should create a new classroom", async () => {
    const newClassroom: Classroom = {
      classroom_id: 0,
      name: "Language Lab",
      capacity: 20,
    };

    const response: StatusResponse<Classroom> =
      await classroomAPI.createClassroom(newClassroom);

    expect(response.status).toBe(201);
    expect(response.data).toMatchObject(newClassroom);
    expect(response.data.classroom_id).toBeDefined();
  });

  // getClassroom
  it("should fetch all classrooms", async () => {
    const response: StatusResponse<Classroom[]> =
      await classroomAPI.getClassrooms();

    expect(response.status).toBe(200);
    expect(response.data.length).toBeGreaterThan(0);
  });

  // getClassroomById
  it("should fetch a classroom by ID", async () => {
    const response: StatusResponse<Classroom> =
      await classroomAPI.getClassroomById(1);

    expect(response.status).toBe(200);
    expect(response.data.classroom_id).toBe(1);
  });

  // 404 by ID
  it("should return 404 for a non-existent classroom by ID", async () => {
    await expect(classroomAPI.getClassroomById(99999)).rejects.toEqual({
      status: 404,
      message: "Classroom not found",
    });
  });

  // getClassroomByName
  it("should fetch a classroom by name", async () => {
    const response: StatusResponse<Classroom> =
      await classroomAPI.getClassroomByName("Science Lab");

    expect(response.status).toBe(200);
    expect(response.data.name).toBe("Science Lab");
  });

  // 404 by name
  it("should return 404 for a non-existent classroom by name", async () => {
    await expect(
      classroomAPI.getClassroomByName("Nonexistent Classroom")
    ).rejects.toEqual({
      status: 404,
      message: "Classroom not found",
    });
  });

  // updateClassroom
  it("should update a classroom", async () => {
    const updatedData = { capacity: 50 };

    const response: StatusResponse<Classroom> =
      await classroomAPI.updateClassroom(1, updatedData);

    expect(response.status).toBe(200);
    expect(response.data.capacity).toBe(50);
  });

  // 404 when updateClassroom
  it("should return 404 when updating a non-existent classroom", async () => {
    await expect(
      classroomAPI.updateClassroom(999, { capacity: 60 })
    ).rejects.toEqual({
      status: 404,
      message: "Classroom not found",
    });
  });

  // deleteClassroom
  it("should delete a classroom", async () => {
    const response: StatusResponse<null> = await classroomAPI.deleteClassroom(
      1
    );

    expect(response.status).toBe(204);
    expect(response.message).toBe("Classroom deleted successfully");
  });

  // 404 when deleteClassroom
  it("should return 404 when deleting a non-existent classroom", async () => {
    await expect(classroomAPI.deleteClassroom(999)).rejects.toEqual({
      status: 404,
      message: "Classroom not found",
    });
  });
});

