"use server";

import Product from "../database/models/product.model";
import User from "../database/models/user.model";
import { connectToDatabase } from "../database/mongoose";
import { handleError } from "../utils";
import {
  CreateNewAndUpdateProductParams,
  DeleteProductProps,
  GetRelatedProductsByCategoryParams,
} from "@/types";
import Category from "../database/models/category.model";
import { revalidatePath } from "next/cache";

const populateProduct = (query: any) => {
  return query
    .populate({
      path: "creator",
      model: User,
      select: "_id firstName lastName",
    })
    .populate({ path: "category", model: Category, select: "_id name" });
};

export const createNewProduct = async ({
  product,
  userId,
}: CreateNewAndUpdateProductParams) => {
  try {
    await connectToDatabase();

    const creator = await User.findById(userId);
    if (!creator) throw new Error("Creator not found");

    const newProduct = await Product.create({
      ...product,
      category: product.categoryId,
      creator: userId,
    });

    await User.findByIdAndUpdate(
      userId,
      { $push: { sellingProducts: newProduct } },
      { new: true }
    );

    return JSON.parse(JSON.stringify(newProduct));
  } catch (error: any) {
    handleError(error);
  }
};

export const getProductById = async (id: string) => {
  try {
    await connectToDatabase();
    const product = await populateProduct(Product.findById(id));
    if (!product) throw new Error("Product not found");

    return JSON.parse(JSON.stringify(product));
  } catch (error: any) {
    handleError(error);
  }
};

export const getCartProducts = async (id: string | undefined) => {
  try {
    await connectToDatabase();

    const userCart = await User.findOne({ clerkId: id }).populate({
      path: "cart",
      populate: {
        path: "product",
        model: Product,
        populate: [
          {
            path: "creator",
            model: User,
            select: "_id firstName lastName",
          },
          {
            path: "category",
            model: Category,
            select: "_id name",
          },
        ],
      },
    });

    if (!userCart || !userCart.cart || userCart.cart.length === 0) {
      console.log("User cart is empty or not found");
      return null; // or throw an error
    }

    return JSON.parse(JSON.stringify(userCart.cart));
  } catch (error) {
    console.error("Error fetching user cart:", error);
    throw error;
  }
};

export const removeProductFromCart = async (
  userId: string | undefined,
  productId: string
) => {
  try {
    await connectToDatabase();
    const user = await User.findOne({ clerkId: userId });

    user.cart = user.cart.filter(
      (product: any) => product._id.toString() !== productId.toString()
    );
    revalidatePath("/cart");
    await user.save();
  } catch (error: any) {
    handleError(error);
  }
};

export const cartCheckout = async (
  userId: string | undefined,
  path: string
) => {
  try {
    await connectToDatabase();

    const user = await User.findOne({ clerkId: userId });

    user.cart = [];

    revalidatePath(path);
    await user.save();
  } catch (error: any) {
    handleError(error);
  }
};

// Designed via basic programming aids
export const getProducts = async (searchQuery?: string) => {
  try {
    await connectToDatabase();

    let conditions: any = {};

    if (searchQuery && searchQuery.trim() !== "") {
      const regex = new RegExp(searchQuery, "i");

      // Find categories matching the search query
      const categories = await Category.find({ name: { $regex: regex } });

      // Extract category IDs from the found categories
      const categoryIds = categories.map((category) => category._id);

      // Add conditions for title matching regex or category matching IDs
      conditions = {
        $or: [{ title: { $regex: regex } }, { category: { $in: categoryIds } }],
      };
    }

    const products = await populateProduct(Product.find(conditions));

    return JSON.parse(JSON.stringify(products));
  } catch (error: any) {
    handleError(error);
  }
};

export const deleteProduct = async ({
  productId,
  path,
}: DeleteProductProps) => {
  try {
    await connectToDatabase();

    const deletedProduct = await Product.findByIdAndDelete(productId);

    if (deletedProduct) revalidatePath(path);
  } catch (error: any) {
    handleError(error);
  }
};

// UPDATE
export const updateProduct = async ({
  userId,
  product,
  productId,
  path,
}: CreateNewAndUpdateProductParams) => {
  try {
    await connectToDatabase();

    const productToUpdate = await Product.findById(productId);

    if (
      !productToUpdate ||
      productToUpdate.creator.toString() !== userId?.toString()
    ) {
      throw new Error("Unauthorized or product not found");
    }

    // Update the product with new values
    const updatedProduct = await Product.findByIdAndUpdate(
      productId,
      { ...product, category: product.categoryId },
      { new: true }
    );

    // Validate the path and revalidate if provided
    if (path) {
      revalidatePath(path);
    }

    return JSON.parse(JSON.stringify(updatedProduct));
  } catch (error) {
    handleError(error);
  }
};

export const getRelatedProductsByCategory = async ({
  categoryId,
  productId,
}: GetRelatedProductsByCategoryParams) => {
  try {
    await connectToDatabase();

    const conditions = {
      $and: [{ category: categoryId }, { _id: { $ne: productId } }],
    };

    const Products = await populateProduct(Product.find(conditions));

    return JSON.parse(JSON.stringify(Products));
  } catch (error) {
    handleError(error);
  }
};

export const getUserSellingProducts = async (userId: string | undefined) => {
  try {
    await connectToDatabase();

    const user = await User.findOne({ clerkId: userId }).populate({
      path: "sellingProducts",
      model: Product,
      populate : [
        {
          path: "creator",
          model: User,
          select: "_id firstName lastName",
        },
        {
          path: "category",
          model: Category,
          select: "_id name",
        },
      ]
    });

    const sellingProducts = user?.sellingProducts;

    return JSON.parse(JSON.stringify(sellingProducts));
  } catch (error) {
    console.log(error)
  }
};

import { number } from "prop-types";


export enum CPFCNPJType
{
    CPF = 1,
        CNPJ = 0
}

export class CPFCNPJValidator{

    _regexNondigit: RegExp = /\D/g;




    _isRepeatingChar(data:string): boolean{

        return data.split('').every((currentChar) => { currentChar === data[0]});
    }

    public RemoveNondigits(field:string):string{
        return field.replace(this._regexNondigit,'');
    }

    public validaCPF(_cpf:string):boolean{

        let cpfNumerico = _cpf.replace(this._regexNondigit,'');
        if(!this._isRepeatingChar(cpfNumerico))
        {
            const mod11 = ( num:number ) => num % 11;

            const toSumOfProducts = ( multiplier:any ) => ( result:any, num:any, i:any ) =>  result + ( num * multiplier-- );

            const getSumOfProducts = ( list:string[], multiplier:number ) => list.reduce( toSumOfProducts(multiplier),0);

            const getValidationDigit = ( multiplier:any ) => ( cpf:string[] ) => getDigit(mod11(getSumOfProducts(cpf, multiplier ) ) );

            const getDigit = ( num:any ) =>   ( num > 1 )  ? 11 - num  : 0;

            let CPF = cpfNumerico.slice(0,9).split('');
            const firstDigit = getValidationDigit(10)(CPF).toString();
            const secondDigit = getValidationDigit(11)(CPF.concat(firstDigit)).toString();

            CPF = CPF.concat(firstDigit);
            CPF = CPF.concat(secondDigit);

            return cpfNumerico === CPF.join('');

            console.log("validaCPF");
        }

        return false;
    }

    public isCPF(cpf:string):boolean{
        let cpfNumerico = cpf.replace(this._regexNondigit,'');

        if(cpfNumerico.length == 11)
            return true;

        return false;
    }

    public formataCPF(cpf:string):string{
        console.log("FormataCPF");
        let cpfNumerico = cpf.replace(this._regexNondigit,'');
        let cpfFormatado = cpfNumerico.replace(/(\d{3})(\d{3})(\d{3})(\d{2})/g,'$1.$2.$3-$4');

        return cpfFormatado;
    }

    public validaCNPJ(cnpj:string):boolean{
        console.log("validaCNPJ");

        let cnpjNumerico = cnpj.replace(this._regexNondigit,'');
        if(!this._isRepeatingChar(cnpjNumerico))
        {
            // Cáculo de validação
	        let t = cnpjNumerico.length - 2,
                d = cnpjNumerico.substring(t),
                d1 = parseInt(d.charAt(0)),
                d2 = parseInt(d.charAt(1)),
                calc = (x:any) => {
                    let n = cnpjNumerico.substring(0, x),
                        y = x - 7,
                        s = 0,
                        r = 0

                        for (let i = x; i >= 1; i--) {
                            s += parseInt(n.charAt(x - i)) * y--;
                            if (y < 2)
                                y = 9
                        }

                        r = 11 - s % 11
                        return r > 9 ? 0 : r
                }

            let firstDigit = calc(t).toString();
            let secondDigt = calc(t+1).toString();
            let CNPJDigitos = '';
            CNPJDigitos = CNPJDigitos.concat(firstDigit);
            CNPJDigitos = CNPJDigitos.concat(secondDigt);

            return cnpjNumerico.substring(12) === CNPJDigitos;

        }
        return false;
    }

    public isCNPJ(cnpj:string):boolean{
        let cnpjNumerico = cnpj.replace(this._regexNondigit,'');

        if(cnpjNumerico.length == 14)
            return true;

        return false;
    }

    public formataCNPJ(cnpj:string):string{
        let cnpjNumerico = cnpj.replace(this._regexNondigit,'');
        //88.044.098/0001-20
        let cnpjFormatado = cnpjNumerico.replace(/(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})/,'$1.$2.$3/$4.$5');

        return cnpjFormatado;
    }
}

import * as THREE from 'three';
import { getCtx } from './get-ctx';

export interface IAudioOptions {
    fftSize?: number;
    fftSmoothingTimeConstant?: number;
}

const DEFAULT_AUDIO_OPTIONS = {
    fftSize: 2048,
    fftSmoothingTimeConstant: 0.8,
};

/**
 * THREE.DataTexture uses a plain object to hold image data instead of ImageData type.
 * This allows us to mutate data on update.
 */
type MutableImageData = {
    data: BufferSource;
    width: number;
    height: number;
};

export default class AudioLoader {
    spectrum: THREE.DataTexture;
    samples: THREE.DataTexture;
    isPlaying = false;
    isEnabled = false;

    private ctx: AudioContext;
    private gain: GainNode;
    private analyser: AnalyserNode;
    private input: MediaStreamAudioSourceNode | null = null;

    private spectrumArray: Uint8Array;
    private samplesArray: Uint8Array;
    private stream: MediaStream | undefined;

    private willPlay: Promise<void> | null = null;

    constructor(rcOpt: IAudioOptions) {
        const rc = {
            ...DEFAULT_AUDIO_OPTIONS,
            ...rcOpt,
        };

        this.ctx = getCtx();
        this.analyser = this.ctx.createAnalyser();
        this.analyser.smoothingTimeConstant = rc.fftSmoothingTimeConstant;
        this.analyser.fftSize = rc.fftSize;

        this.gain = this.ctx.createGain();
        this.gain.gain.setValueAtTime(0, this.ctx.currentTime);

        this.analyser.connect(this.gain);
        this.gain.connect(this.ctx.destination);

        this.spectrumArray = new Uint8Array(this.analyser.frequencyBinCount);
        this.samplesArray = new Uint8Array(this.analyser.frequencyBinCount);

        this.spectrum = new THREE.DataTexture(
            this.spectrumArray,
            this.analyser.frequencyBinCount,
            1,
            THREE.LuminanceFormat,
            THREE.UnsignedByteType,
        );
        this.samples = new THREE.DataTexture(
            this.samplesArray,
            this.analyser.frequencyBinCount,
            1,
            THREE.LuminanceFormat,
            THREE.UnsignedByteType,
        );
    }

    enable(): void {
        this.willPlay = (async () => {
            try {
                const stream = await navigator.mediaDevices.getUserMedia({
                    audio: true,
                });
                this.stream = stream;
                this.input = this.ctx.createMediaStreamSource(stream);
                this.input.connect(this.analyser);
                this.isEnabled = true;
            } catch (e) {
                console.error(e);
            }
        })();
    }

    disable(): void {
        if (this.isEnabled && this.willPlay) {
            this.willPlay.then(() => {
                this.isEnabled = false;
                this.input && this.input.disconnect();
                this.stream
                    ?.getTracks()
                    .forEach((t: MediaStreamTrack) => t.stop());
            });
        }
    }

    update(): void {
        this.analyser.getByteFrequencyData(this.spectrumArray);
        this.analyser.getByteTimeDomainData(this.samplesArray);
        this.spectrum.needsUpdate = true;
        this.samples.needsUpdate = true;
    }

    getVolume(): number {
        let v = 0;
        this.samplesArray.forEach((x) => {
            v += Math.pow(x / 128 - 1, 2);
        });
        const rms = Math.sqrt(v / this.samplesArray.length);
        return rms;
    }

    setFftSize(fftSize: number): void {
        this.analyser.fftSize = fftSize;
        this.spectrumArray = new Uint8Array(this.analyser.frequencyBinCount);
        this.samplesArray = new Uint8Array(this.analyser.frequencyBinCount);

        const spectrumImage = this.spectrum.image as MutableImageData;
        spectrumImage.data = this.spectrumArray;
        spectrumImage.width = this.analyser.frequencyBinCount;

        const samplesImage = this.samples.image as MutableImageData;
        samplesImage.data = this.samplesArray;
        samplesImage.width = this.analyser.frequencyBinCount;
    }

    setFftSmoothingTimeConstant(fftSmoothingTimeConstant: number): void {
        this.analyser.smoothingTimeConstant = fftSmoothingTimeConstant;
    }
}

import { Subject } from 'rxjs'

import { BzzFeed, FEED_ZERO_TOPIC } from '@erebos/bzz-feed'
import { BzzNode } from '@erebos/bzz-node'
import { pubKeyToAddress } from '@erebos/keccak256'
import { createKeyPair, sign } from '@erebos/secp256k1'

describe('bzz-feed', () => {
  const sleep = async (time = 1000): Promise<void> => {
    await new Promise(resolve => {
      setTimeout(resolve, time)
    })
  }

  const keyPair = createKeyPair()
  const user = pubKeyToAddress(keyPair.getPublic('array'))

  const bzz = new BzzNode({ url: 'http://localhost:8500' })
  const bzzFeed = new BzzFeed({
    bzz,
    signBytes: (bytes: Array<number>) => Promise.resolve(sign(bytes, keyPair)),
  })

  let uploadContent: string

  beforeEach(() => {
    uploadContent = Math.random()
      .toString(36)
      .slice(2)
  })

  it('supports setting and getting a chunk', async () => {
    const params = { user, name: uploadContent }
    const data = { test: uploadContent }
    await bzzFeed.setChunk(params, data)
    const res = await bzzFeed.getChunk(params)
    const value = await res.json()
    expect(value).toEqual(data)
  })

  it('creates a manifest', async () => {
    const hash = await bzzFeed.createManifest({ user, name: 'manifest' })
    expect(hash).toBeDefined()
  })

  it('uploads data and sets the feed chunk', async () => {
    jest.setTimeout(20000)
    const manifestHash = await bzzFeed.createManifest({
      user,
      name: uploadContent,
    })
    await bzzFeed.setContent(manifestHash, 'hello', {
      contentType: 'text/plain',
    })
    const res = await bzz.download(manifestHash)
    const value = await res.text()
    expect(value).toBe('hello')
  })

  it('sets and gets the feed content hash', async () => {
    const feedParams = { user, name: uploadContent }
    const uploadedHash = await bzz.uploadFile('hello', {
      contentType: 'text/plain',
    })
    await bzzFeed.setContentHash(feedParams, uploadedHash)
    const contentHash = await bzzFeed.getContentHash(feedParams)
    expect(contentHash).toBe(uploadedHash)
  })

  it('sets and gets the feed content', async () => {
    const feedParams = { user, name: uploadContent }
    await bzzFeed.setContent(feedParams, 'hello', {
      contentType: 'text/plain',
    })
    const res = await bzzFeed.getContent(feedParams)
    const text = await res.text()
    expect(text).toBe('hello')
  })

  it('sets and gets the raw feed content hash', async () => {
    const feedParams = { user, topic: FEED_ZERO_TOPIC, time: 0, level: 0 }
    const uploadedHash = await bzz.uploadFile('hello', {
      contentType: 'text/plain',
    })
    await bzzFeed.setRawContentHash(feedParams, uploadedHash)
    const contentHash = await bzzFeed.getRawContentHash(feedParams)
    expect(contentHash).toBe(uploadedHash)
  })

  it('sets and gets the raw feed content', async () => {
    const feedParams = { user, topic: FEED_ZERO_TOPIC, time: 0, level: 0 }
    await bzzFeed.setRawContent(feedParams, 'hello', {
      contentType: 'text/plain',
    })
    const res = await bzzFeed.getRawContent(feedParams)
    const text = await res.text()
    expect(text).toBe('hello')
  })

  it('supports chunk polling', done => {
    jest.setTimeout(40000)

    let step = '0-idle'
    let expectedValue: string

    const params = { user, name: uploadContent }
    const subscription = bzzFeed
      .pollChunk(params, { interval: 2000 })
      // eslint-disable-next-line @typescript-eslint/no-misused-promises
      .subscribe(async res => {
        /* eslint-disable require-atomic-updates */
        if (res === null) {
          if (step === '0-idle') {
            step = '1-first-value-post'
            await bzzFeed.setChunk(params, 'hello')
            expectedValue = 'hello'

            step = '2-first-value-posted'
          }
        } else {
          const value = await res.text()
          if (step === '2-first-value-posted') {
            expect(value).toBe(expectedValue)
            step = '3-first-value-received'
            await sleep(5000)
            step = '4-second-value-post'
            await bzzFeed.setChunk(params, 'world')
            expectedValue = 'world'
            step = '5-second-value-posted'
          } else if (step === '5-second-value-posted') {
            expect(value).toBe(expectedValue)
            subscription.unsubscribe()
            step = '6-unsubscribed'
            await sleep(5000)
            done()
          } else if (step === '6-unsubscribed') {
            throw new Error('Event received after unsubscribed')
          }
        }
        /* eslint-enable require-atomic-updates */
      })
  })

  it('supports feed content hash polling', done => {
    jest.setTimeout(40000)

    const params = { user, name: uploadContent }
    const post = async (value: string): Promise<string> => {
      return await bzzFeed.setContent(params, value, {
        contentType: 'text/plain',
      })
    }

    let step = '0-idle'
    let expectedHash: string
    let previousValue: string

    const subscription = bzzFeed
      .pollContentHash(params, {
        interval: 5000,
        changedOnly: true,
      })
      // eslint-disable-next-line @typescript-eslint/no-misused-promises
      .subscribe(async value => {
        /* eslint-disable require-atomic-updates */
        if (value === null) {
          if (step === '0-idle') {
            step = '1-first-value-post'
            expectedHash = await post('hello')
            step = '2-first-value-posted'
          }
        } else {
          expect(value).not.toBe(previousValue)
          previousValue = value

          if (step === '2-first-value-posted') {
            expect(value).toBe(expectedHash)
            step = '3-first-value-received'
            await sleep(8000)
            step = '4-second-value-post'
            expectedHash = await post('world')
            step = '5-second-value-posted'
          } else if (step === '5-second-value-posted') {
            expect(value).toBe(expectedHash)
            subscription.unsubscribe()
            done()
          }
        }
        /* eslint-enable require-atomic-updates */
      })
  })

  it('supports feed content polling', done => {
    jest.setTimeout(40000)

    const params = { user, name: uploadContent }
    const post = async (value: string): Promise<string> => {
      return await bzzFeed.setContent(params, value, {
        contentType: 'text/plain',
      })
    }

    let step = '0-idle'
    let expectedValue: string

    const subscription = bzzFeed
      .pollContent(params, {
        interval: 5000,
        changedOnly: true,
      })
      // eslint-disable-next-line @typescript-eslint/no-misused-promises
      .subscribe(async res => {
        /* eslint-disable require-atomic-updates */
        if (res === null) {
          if (step === '0-idle') {
            step = '1-first-value-post'
            await post('hello')
            expectedValue = 'hello'
            step = '2-first-value-posted'
          }
        } else {
          const value = await res.text()

          if (step === '2-first-value-posted') {
            expect(value).toBe(expectedValue)
            step = '3-first-value-received'
            await sleep(8000)
            step = '4-second-value-post'
            await post('world')
            expectedValue = 'world'
            step = '5-second-value-posted'
          } else if (step === '5-second-value-posted') {
            expect(value).toBe(expectedValue)
            subscription.unsubscribe()
            done()
          }
        }
        /* eslint-enable require-atomic-updates */
      })
  })

  it('feed polling fails on not found error if the option is enabled', done => {
    jest.setTimeout(10000)

    bzzFeed
      .pollChunk(
        { user, name: 'notfound' },
        { interval: 2000, whenEmpty: 'error', immediate: false },
      )
      .subscribe({
        next: () => {
          throw new Error('Subscription should not have emitted a value')
        },
        error: () => {
          done()
        },
      })
  })

  it('feed polling accepts an external trigger', done => {
    const trigger: Subject<void> = new Subject()
    const subscription = bzzFeed
      .pollChunk(
        { user, name: 'notfound' },
        { interval: 10000, immediate: false, trigger },
      )
      .subscribe(() => {
        subscription.unsubscribe()
        done()
      })
    // Test should timeout if the trigger is not executed
    trigger.next()
  })
})

'use strict';

import * as path from 'path';
import * as vscode from 'vscode';
import { configurationSettings } from './globals/enums';

export class JsonEditorPanel {
    public static currentPanel: JsonEditorPanel | undefined;

    private static readonly viewType: string = 'jsonEditor';
    private static readonly extensionPrefix: string = 'vscode-json-editor';

    private readonly _panel: vscode.WebviewPanel;
    private readonly _extensionPath: string;
    private _disposables: vscode.Disposable[] = [];
    private _currentEditor: vscode.TextEditor;

    private constructor(extensionPath: string, column: vscode.ViewColumn, theme: string) {
        this._extensionPath = extensionPath;
        this._currentEditor = vscode.window.activeTextEditor;
        this._panel = vscode.window.createWebviewPanel(JsonEditorPanel.viewType, "Json editor", column, {
            enableScripts: true,
            localResourceRoots: [
                vscode.Uri.file(path.join(this._extensionPath, 'jsoneditor'))
            ]
        });
        this._panel.webview.html = this.getHtmlForWebview(this._extensionPath, theme);

        this._panel.onDidDispose(() => this.dispose(), null, this._disposables);

        this._panel.webview.onDidReceiveMessage(message => {
            if (this._currentEditor) {
                this._currentEditor.edit(editBuilder => {
                    const range: vscode.Range = new vscode.Range(
                        this._currentEditor.document.positionAt(0),
                        this._currentEditor.document.positionAt(this._currentEditor.document.getText().length)
                    );

                    editBuilder.replace(range, message.json);
                });
            }
        });

        vscode.window.onDidChangeActiveTextEditor(() => this.onActiveEditorChanged());
        vscode.workspace.onDidSaveTextDocument(() => this.onDocumentChanged());

        this.onActiveEditorChanged();
    }

    // tslint:disable-next-line:function-name
    public static CreateOrShow(extensionPath: string): void {
        const column = vscode.ViewColumn.Three;
        const config: vscode.WorkspaceConfiguration = vscode.workspace.getConfiguration(this.extensionPrefix);
        const theme: string = config.get(configurationSettings.theme);

        if (JsonEditorPanel.currentPanel) {
            JsonEditorPanel.currentPanel._panel.reveal(column);
        } else {
            JsonEditorPanel.currentPanel = new JsonEditorPanel(extensionPath, column, theme);
        }
    }

    public dispose(): void {
        JsonEditorPanel.currentPanel = undefined;

        this._panel.dispose();

        while (this._disposables.length) {
            const x = this._disposables.pop();
            if (x) {
                x.dispose();
            }
        }
    }

    private getJson(): string {
        let json: string = "";
        if (this._currentEditor) {
            json = this._currentEditor.document.getText();
        }
        return json;
    }

    private onActiveEditorChanged(): void {
        if (vscode.window.activeTextEditor) {
            this._currentEditor = vscode.window.activeTextEditor;
            const json: string = this.getJson();
            this._panel.webview.postMessage({ json: json });
        }
    }

    private onDocumentChanged(): void {
        const json: string = this.getJson();
        this._panel.webview.postMessage({ json: json });
    }

    private getHtmlForWebview(extensionPath: string, theme: string): string {
        const mainScriptPathOnDisk = vscode.Uri.file(path.join(extensionPath, 'jsoneditor', 'main.js'));
        const mainScriptUri = mainScriptPathOnDisk.with({ scheme: 'vscode-resource' });
        const scriptPathOnDisk = vscode.Uri.file(path.join(extensionPath, 'jsoneditor', 'jsoneditor.min.js'));
        const scriptUri = scriptPathOnDisk.with({ scheme: 'vscode-resource' });

        const cssPathOnDisk = vscode.Uri.file(path.join(extensionPath, 'jsoneditor', 'jsoneditor.min.css'));
        const cssUri = cssPathOnDisk.with({ scheme: 'vscode-resource' });

        const cssDarkPathOnDisk = vscode.Uri.file(path.join(extensionPath, 'jsoneditor', 'jsoneditor.dark.min.css'));
        const cssDarkUri = cssDarkPathOnDisk.with({ scheme: 'vscode-resource' });
        const darkTheme: string = theme === 'dark' ? `<link href="${cssDarkUri}" rel="stylesheet" type="text/css">` : '';

        return `
        <!DOCTYPE HTML>
        <html>
        <head>
            <!-- when using the mode "code", it's important to specify charset utf-8 -->
            <meta http-equiv="Content-Type" content="text/html;charset=utf-8">

            <link href="${cssUri}" rel="stylesheet" type="text/css">
            ${darkTheme}
            <script src="${scriptUri}"></script>
        </head>
        <body>
            <div id="jsoneditor"></div>

            <script src="${mainScriptUri}"></script>
        </body>
        </html>
        `;
    }
}

import {
  validateFiniteNumber,
  validateIntegerNumber,
  validateNegativeFiniteNumber,
  validateNegativeFiniteNumberOrZero,
  validateNegativeIntegerNumber,
  validateNegativeNumber,
  validatePositiveFiniteNumber,
  validatePositiveFiniteNumberOrZero,
  validatePositiveIntegerNumber,
  validatePositiveNumber,
  validateZero,
} from './validation';

const positiveZero = 0;
const negativeZero = -0;
const positiveInteger = 1;
const negativeInteger = -1;
const positiveFloat = 0.1;
const negativeFloat = -0.1;
const positiveInfinity = Infinity;
const negativeInfinity = -Infinity;
const bigPositiveInteger = 100000000000000000000000000000000;
const bigNegativeInteger = -100000000000000000000000000000000;
const smallPositiveFloat = 0.0000000000000000000000000000001;
const smallNegativeFloat = -0.0000000000000000000000000000001;
const positiveZeroString = '0';
const negativeZeroString = '-0';
const positiveIntegerString = '1';
const negativeIntegerString = '-1';
const positiveFloatString = '0.1';
const negativeFloatString = '-0.1';
const positiveInfinityString = 'Infinity';
const negativeInfinityString = '-Infinity';
const bigPositiveIntegerString = '100000000000000000000000000000';
const bigNegativeIntegerString = '-100000000000000000000000000000';
const smallPositiveFloatString = '0.0000000000000000000000000000001';
const smallNegativeFloatString = '-0.0000000000000000000000000000001';

// Function to test that validators throw errors.
function getTester(fn: (v: any) => void, v: any): () => void {
  return () => fn(v);
}

describe('BigNumber Validation Functions', () => {
  describe('validateFiniteNumber', () => {
    it('should validate as expected', () => {
      expect(getTester(validateFiniteNumber, positiveZero)).not.toThrow();
      expect(getTester(validateFiniteNumber, negativeZero)).not.toThrow();
      expect(getTester(validateFiniteNumber, positiveInteger)).not.toThrow();
      expect(getTester(validateFiniteNumber, negativeInteger)).not.toThrow();
      expect(getTester(validateFiniteNumber, positiveFloat)).not.toThrow();
      expect(getTester(validateFiniteNumber, negativeFloat)).not.toThrow();
      expect(getTester(validateFiniteNumber, positiveInfinity)).toThrow();
      expect(getTester(validateFiniteNumber, negativeInfinity)).toThrow();
      expect(getTester(validateFiniteNumber, bigPositiveInteger)).not.toThrow();
      expect(getTester(validateFiniteNumber, bigNegativeInteger)).not.toThrow();
      expect(getTester(validateFiniteNumber, smallPositiveFloat)).not.toThrow();
      expect(getTester(validateFiniteNumber, smallNegativeFloat)).not.toThrow();
      expect(getTester(validateFiniteNumber, positiveZeroString)).not.toThrow();
      expect(getTester(validateFiniteNumber, negativeZeroString)).not.toThrow();
      expect(getTester(validateFiniteNumber, positiveIntegerString)).not.toThrow();
      expect(getTester(validateFiniteNumber, negativeIntegerString)).not.toThrow();
      expect(getTester(validateFiniteNumber, positiveFloatString)).not.toThrow();
      expect(getTester(validateFiniteNumber, negativeFloatString)).not.toThrow();
      expect(getTester(validateFiniteNumber, positiveInfinityString)).toThrow();
      expect(getTester(validateFiniteNumber, negativeInfinityString)).toThrow();
      expect(getTester(validateFiniteNumber, bigPositiveIntegerString)).not.toThrow();
      expect(getTester(validateFiniteNumber, bigNegativeIntegerString)).not.toThrow();
      expect(getTester(validateFiniteNumber, smallPositiveFloatString)).not.toThrow();
      expect(getTester(validateFiniteNumber, smallNegativeFloatString)).not.toThrow();
    });
  });

  describe('validateZero', () => {
    it('should validate as expected', () => {
      expect(getTester(validateZero, positiveZero)).not.toThrow();
      expect(getTester(validateZero, negativeZero)).not.toThrow();
      expect(getTester(validateZero, positiveInteger)).toThrow();
      expect(getTester(validateZero, negativeInteger)).toThrow();
      expect(getTester(validateZero, positiveFloat)).toThrow();
      expect(getTester(validateZero, negativeFloat)).toThrow();
      expect(getTester(validateZero, positiveInfinity)).toThrow();
      expect(getTester(validateZero, negativeInfinity)).toThrow();
      expect(getTester(validateZero, bigPositiveInteger)).toThrow();
      expect(getTester(validateZero, bigNegativeInteger)).toThrow();
      expect(getTester(validateZero, smallPositiveFloat)).toThrow();
      expect(getTester(validateZero, smallNegativeFloat)).toThrow();
      expect(getTester(validateZero, positiveZeroString)).not.toThrow();
      expect(getTester(validateZero, negativeZeroString)).not.toThrow();
      expect(getTester(validateZero, positiveIntegerString)).toThrow();
      expect(getTester(validateZero, negativeIntegerString)).toThrow();
      expect(getTester(validateZero, positiveFloatString)).toThrow();
      expect(getTester(validateZero, negativeFloatString)).toThrow();
      expect(getTester(validateZero, positiveInfinityString)).toThrow();
      expect(getTester(validateZero, negativeInfinityString)).toThrow();
      expect(getTester(validateZero, bigPositiveIntegerString)).toThrow();
      expect(getTester(validateZero, bigNegativeIntegerString)).toThrow();
      expect(getTester(validateZero, smallPositiveFloatString)).toThrow();
      expect(getTester(validateZero, smallNegativeFloatString)).toThrow();
    });
  });

  describe('validatePositiveNumber', () => {
    it('should validate as expected', () => {
      expect(getTester(validatePositiveNumber, positiveZero)).toThrow();
      expect(getTester(validatePositiveNumber, negativeZero)).toThrow();
      expect(getTester(validatePositiveNumber, positiveInteger)).not.toThrow();
      expect(getTester(validatePositiveNumber, negativeInteger)).toThrow();
      expect(getTester(validatePositiveNumber, positiveFloat)).not.toThrow();
      expect(getTester(validatePositiveNumber, negativeFloat)).toThrow();
      expect(getTester(validatePositiveNumber, positiveInfinity)).not.toThrow();
      expect(getTester(validatePositiveNumber, negativeInfinity)).toThrow();
      expect(getTester(validatePositiveNumber, bigPositiveInteger)).not.toThrow();
      expect(getTester(validatePositiveNumber, bigNegativeInteger)).toThrow();
      expect(getTester(validatePositiveNumber, smallPositiveFloat)).not.toThrow();
      expect(getTester(validatePositiveNumber, smallNegativeFloat)).toThrow();
      expect(getTester(validatePositiveNumber, positiveZeroString)).toThrow();
      expect(getTester(validatePositiveNumber, negativeZeroString)).toThrow();
      expect(getTester(validatePositiveNumber, positiveIntegerString)).not.toThrow();
      expect(getTester(validatePositiveNumber, negativeIntegerString)).toThrow();
      expect(getTester(validatePositiveNumber, positiveFloatString)).not.toThrow();
      expect(getTester(validatePositiveNumber, negativeFloatString)).toThrow();
      expect(getTester(validatePositiveNumber, positiveInfinityString)).not.toThrow();
      expect(getTester(validatePositiveNumber, negativeInfinityString)).toThrow();
      expect(getTester(validatePositiveNumber, bigPositiveIntegerString)).not.toThrow();
      expect(getTester(validatePositiveNumber, bigNegativeIntegerString)).toThrow();
      expect(getTester(validatePositiveNumber, smallPositiveFloatString)).not.toThrow();
      expect(getTester(validatePositiveNumber, smallNegativeFloatString)).toThrow();
    });
  });

  describe('validateNegativeNumber', () => {
    it('should validate as expected', () => {
      expect(getTester(validateNegativeNumber, positiveZero)).toThrow();
      expect(getTester(validateNegativeNumber, negativeZero)).toThrow();
      expect(getTester(validateNegativeNumber, positiveInteger)).toThrow();
      expect(getTester(validateNegativeNumber, negativeInteger)).not.toThrow();
      expect(getTester(validateNegativeNumber, positiveFloat)).toThrow();
      expect(getTester(validateNegativeNumber, negativeFloat)).not.toThrow();
      expect(getTester(validateNegativeNumber, positiveInfinity)).toThrow();
      expect(getTester(validateNegativeNumber, negativeInfinity)).not.toThrow();
      expect(getTester(validateNegativeNumber, bigPositiveInteger)).toThrow();
      expect(getTester(validateNegativeNumber, bigNegativeInteger)).not.toThrow();
      expect(getTester(validateNegativeNumber, smallPositiveFloat)).toThrow();
      expect(getTester(validateNegativeNumber, smallNegativeFloat)).not.toThrow();
      expect(getTester(validateNegativeNumber, positiveZeroString)).toThrow();
      expect(getTester(validateNegativeNumber, negativeZeroString)).toThrow();
      expect(getTester(validateNegativeNumber, positiveIntegerString)).toThrow();
      expect(getTester(validateNegativeNumber, negativeIntegerString)).not.toThrow();
      expect(getTester(validateNegativeNumber, positiveFloatString)).toThrow();
      expect(getTester(validateNegativeNumber, negativeFloatString)).not.toThrow();
      expect(getTester(validateNegativeNumber, positiveInfinityString)).toThrow();
      expect(getTester(validateNegativeNumber, negativeInfinityString)).not.toThrow();
      expect(getTester(validateNegativeNumber, bigPositiveIntegerString)).toThrow();
      expect(getTester(validateNegativeNumber, bigNegativeIntegerString)).not.toThrow();
      expect(getTester(validateNegativeNumber, smallPositiveFloatString)).toThrow();
      expect(getTester(validateNegativeNumber, smallNegativeFloatString)).not.toThrow();
    });
  });

  describe('validatePositiveFiniteNumber', () => {
    it('should validate as expected', () => {
      expect(getTester(validatePositiveFiniteNumber, positiveZero)).toThrow();
      expect(getTester(validatePositiveFiniteNumber, negativeZero)).toThrow();
      expect(getTester(validatePositiveFiniteNumber, positiveInteger)).not.toThrow();
      expect(getTester(validatePositiveFiniteNumber, negativeInteger)).toThrow();
      expect(getTester(validatePositiveFiniteNumber, positiveFloat)).not.toThrow();
      expect(getTester(validatePositiveFiniteNumber, negativeFloat)).toThrow();
      expect(getTester(validatePositiveFiniteNumber, positiveInfinity)).toThrow();
      expect(getTester(validatePositiveFiniteNumber, negativeInfinity)).toThrow();
      expect(getTester(validatePositiveFiniteNumber, bigPositiveInteger)).not.toThrow();
      expect(getTester(validatePositiveFiniteNumber, bigNegativeInteger)).toThrow();
      expect(getTester(validatePositiveFiniteNumber, smallPositiveFloat)).not.toThrow();
      expect(getTester(validatePositiveFiniteNumber, smallNegativeFloat)).toThrow();
      expect(getTester(validatePositiveFiniteNumber, positiveZeroString)).toThrow();
      expect(getTester(validatePositiveFiniteNumber, negativeZeroString)).toThrow();
      expect(getTester(validatePositiveFiniteNumber, positiveIntegerString)).not.toThrow();
      expect(getTester(validatePositiveFiniteNumber, negativeIntegerString)).toThrow();
      expect(getTester(validatePositiveFiniteNumber, positiveFloatString)).not.toThrow();
      expect(getTester(validatePositiveFiniteNumber, negativeFloatString)).toThrow();
      expect(getTester(validatePositiveFiniteNumber, positiveInfinityString)).toThrow();
      expect(getTester(validatePositiveFiniteNumber, negativeInfinityString)).toThrow();
      expect(getTester(validatePositiveFiniteNumber, bigPositiveIntegerString)).not.toThrow();
      expect(getTester(validatePositiveFiniteNumber, bigNegativeIntegerString)).toThrow();
      expect(getTester(validatePositiveFiniteNumber, smallPositiveFloatString)).not.toThrow();
      expect(getTester(validatePositiveFiniteNumber, smallNegativeFloatString)).toThrow();
    });
  });

  describe('validateNegativeFiniteNumber', () => {
    it('should validate as expected', () => {
      expect(getTester(validateNegativeFiniteNumber, positiveZero)).toThrow();
      expect(getTester(validateNegativeFiniteNumber, negativeZero)).toThrow();
      expect(getTester(validateNegativeFiniteNumber, positiveInteger)).toThrow();
      expect(getTester(validateNegativeFiniteNumber, negativeInteger)).not.toThrow();
      expect(getTester(validateNegativeFiniteNumber, positiveFloat)).toThrow();
      expect(getTester(validateNegativeFiniteNumber, negativeFloat)).not.toThrow();
      expect(getTester(validateNegativeFiniteNumber, positiveInfinity)).toThrow();
      expect(getTester(validateNegativeFiniteNumber, negativeInfinity)).toThrow();
      expect(getTester(validateNegativeFiniteNumber, bigPositiveInteger)).toThrow();
      expect(getTester(validateNegativeFiniteNumber, bigNegativeInteger)).not.toThrow();
      expect(getTester(validateNegativeFiniteNumber, smallPositiveFloat)).toThrow();
      expect(getTester(validateNegativeFiniteNumber, smallNegativeFloat)).not.toThrow();
      expect(getTester(validateNegativeFiniteNumber, positiveZeroString)).toThrow();
      expect(getTester(validateNegativeFiniteNumber, negativeZeroString)).toThrow();
      expect(getTester(validateNegativeFiniteNumber, positiveIntegerString)).toThrow();
      expect(getTester(validateNegativeFiniteNumber, negativeIntegerString)).not.toThrow();
      expect(getTester(validateNegativeFiniteNumber, positiveFloatString)).toThrow();
      expect(getTester(validateNegativeFiniteNumber, negativeFloatString)).not.toThrow();
      expect(getTester(validateNegativeFiniteNumber, positiveInfinityString)).toThrow();
      expect(getTester(validateNegativeFiniteNumber, negativeInfinityString)).toThrow();
      expect(getTester(validateNegativeFiniteNumber, bigPositiveIntegerString)).toThrow();
      expect(getTester(validateNegativeFiniteNumber, bigNegativeIntegerString)).not.toThrow();
      expect(getTester(validateNegativeFiniteNumber, smallPositiveFloatString)).toThrow();
      expect(getTester(validateNegativeFiniteNumber, smallNegativeFloatString)).not.toThrow();
    });
  });

  describe('validatePositiveFiniteNumberOrZero', () => {
    it('should validate as expected', () => {
      expect(getTester(validatePositiveFiniteNumberOrZero, positiveZero)).not.toThrow();
      expect(getTester(validatePositiveFiniteNumberOrZero, negativeZero)).not.toThrow();
      expect(getTester(validatePositiveFiniteNumberOrZero, positiveInteger)).not.toThrow();
      expect(getTester(validatePositiveFiniteNumberOrZero, negativeInteger)).toThrow();
